	"LEAD_TIME_DAYS" NUMBER,
	"EXCLUSIONS" VARCHAR2(2000) COLLATE "USING_NLS_COMP",
	"SCOPE_VARIANCE_FLAG" VARCHAR2(1) COLLATE "USING_NLS_COMP" DEFAULT 'N' NOT NULL ENABLE,
	"IS_SELECTED" VARCHAR2(1) COLLATE "USING_NLS_COMP" DEFAULT 'N' NOT NULL ENABLE,
