  CREATE TABLE "SGINT02"."FC_RESEARCH_FINDINGS"
   (	"FINDING_ID" NUMBER GENERATED BY DEFAULT AS IDENTITY MINVALUE 1 MAXVALUE 9999999999999999999999999999 INCREMENT BY 1 START WITH 1 CACHE 20 NOORDER  NOCYCLE  NOKEEP  NOSCALE  NOT NULL ENABLE,
	"TENDER_ID" NUMBER NOT NULL ENABLE,
	"TOPIC" VARCHAR2(100) COLLATE "USING_NLS_COMP" NOT NULL ENABLE,
	"CLAIM_TEXT" VARCHAR2(4000) COLLATE "USING_NLS_COMP" NOT NULL ENABLE,
	"SOURCE_URL" VARCHAR2(500) COLLATE "USING_NLS_COMP" NOT NULL ENABLE,
	"PAGE_TITLE" VARCHAR2(255) COLLATE "USING_NLS_COMP",
	"PUBLISHER" VARCHAR2(100) COLLATE "USING_NLS_COMP",
