	"REVIEWED_BY" VARCHAR2(50) COLLATE "USING_NLS_COMP",
	"REVIEWED_AT" TIMESTAMP (6) WITH LOCAL TIME ZONE,
	 CHECK (confidence_score BETWEEN 0 AND 100) ENABLE,
	 CHECK (review_status IN ('PENDING', 'APPROVED', 'REJECTED')) ENABLE,
	 PRIMARY KEY ("FINDING_ID")
  USING INDEX  ENABLE
   )  DEFAULT COLLATION "USING_NLS_COMP" ;


  CREATE TABLE "SGINT02"."FC_RFQS"
   (	"RFQ_ID" NUMBER GENERATED BY DEFAULT AS IDENTITY MINVALUE 1 MAXVALUE 9999999999999999999999999999 INCREMENT BY 1 START WITH 1 CACHE 20 NOORDER  NOCYCLE  NOKEEP  NOSCALE  NOT NULL ENABLE,
	"TENDER_ID" NUMBER NOT NULL ENABLE,
	"RFQ_CODE" VARCHAR2(30) COLLATE "USING_NLS_COMP" NOT NULL ENABLE,
	"VENDOR_NAME" VARCHAR2(100) COLLATE "USING_NLS_COMP" NOT NULL ENABLE,
	"VENDOR_EMAIL" VARCHAR2(100) COLLATE "USING_NLS_COMP" NOT NULL ENABLE,
	"SPEC_VERSION" NUMBER(4,1) DEFAULT 1.0 NOT NULL ENABLE,
	"DRAFT_EMAIL_BODY" VARCHAR2(4000) COLLATE "USING_NLS_COMP" NOT NULL ENABLE,
	"SENT_DATE" DATE,
	"DUE_DATE" DATE NOT NULL ENABLE,
	"STATUS" VARCHAR2(20) COLLATE "USING_NLS_COMP" DEFAULT 'DRAFT' NOT NULL ENABLE,
	"REVIEWED_BY" VARCHAR2(50) COLLATE "USING_NLS_COMP",
	 PRIMARY KEY ("RFQ_ID")
  USING INDEX  ENABLE,
	 UNIQUE ("RFQ_CODE")
  USING INDEX  ENABLE,
	 CONSTRAINT "CHK_FC_RFQS_STATUS" CHECK (status IN ('DRAFT', 'SENT', 'DISPATCHED', 'QUOTED', 'CANCELLED')) ENABLE
   )  DEFAULT COLLATION "USING_NLS_COMP" ;


  CREATE TABLE "SGINT02"."FC_SPATIAL_CHECKS"
   (	"CHECK_ID" NUMBER GENERATED BY DEFAULT AS IDENTITY MINVALUE 1 MAXVALUE 9999999999999999999999999999 INCREMENT BY 1 START WITH 1 CACHE 20 NOORDER  NOCYCLE  NOKEEP  NOSCALE  NOT NULL ENABLE,
	"TENDER_ID" NUMBER NOT NULL ENABLE,
	"VENUE_ID" NUMBER NOT NULL ENABLE,
	"STRUCTURE_NAME" VARCHAR2(150) COLLATE "USING_NLS_COMP" NOT NULL ENABLE,
	"REQ_LENGTH_M" NUMBER(6,2) NOT NULL ENABLE,
	"REQ_WIDTH_M" NUMBER(6,2) NOT NULL ENABLE,
	"REQ_HEIGHT_M" NUMBER(6,2) NOT NULL ENABLE,
	"FEASIBILITY_STATUS" VARCHAR2(20) COLLATE "USING_NLS_COMP" DEFAULT 'UNKNOWN' NOT NULL ENABLE,
	"CLEARANCE_DELTA_M" NUMBER(6,2),
	"ASSUMPTIONS_LOG" VARCHAR2(2000) COLLATE "USING_NLS_COMP",
	"EVALUATED_BY" VARCHAR2(50) COLLATE "USING_NLS_COMP",
	"EVALUATED_AT" TIMESTAMP (6) WITH LOCAL TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL ENABLE,
