	 PRIMARY KEY ("CHECK_ID")
  USING INDEX  ENABLE
   )  DEFAULT COLLATION "USING_NLS_COMP" ;


  CREATE TABLE "SGINT02"."FC_TENDERS"
   (	"TENDER_ID" NUMBER GENERATED BY DEFAULT AS IDENTITY MINVALUE 1 MAXVALUE 9999999999999999999999999999 INCREMENT BY 1 START WITH 1 CACHE 20 NOORDER  NOCYCLE  NOKEEP  NOSCALE  NOT NULL ENABLE,
	"TENDER_CODE" VARCHAR2(30) COLLATE "USING_NLS_COMP" NOT NULL ENABLE,
	"CLIENT_NAME" VARCHAR2(100) COLLATE "USING_NLS_COMP" NOT NULL ENABLE,
	"PROJECT_TITLE" VARCHAR2(200) COLLATE "USING_NLS_COMP" NOT NULL ENABLE,
	"OFFICE" VARCHAR2(10) COLLATE "USING_NLS_COMP" DEFAULT 'SG' NOT NULL ENABLE,
	"CURRENT_STAGE" VARCHAR2(30) COLLATE "USING_NLS_COMP" DEFAULT 'INTAKE_REVIEW' NOT NULL ENABLE,
	"STATUS" VARCHAR2(30) COLLATE "USING_NLS_COMP" DEFAULT 'ACTIVE' NOT NULL ENABLE,
	"SUBMISSION_DEADLINE" DATE NOT NULL ENABLE,
	"PRIMARY_CURRENCY" VARCHAR2(5) COLLATE "USING_NLS_COMP" DEFAULT 'SGD' NOT NULL ENABLE,
	"SPONSOR_USER" VARCHAR2(50) COLLATE "USING_NLS_COMP" NOT NULL ENABLE,
	"PLANNING_LEAD" VARCHAR2(50) COLLATE "USING_NLS_COMP" NOT NULL ENABLE,
	"DESIGNER_USER" VARCHAR2(50) COLLATE "USING_NLS_COMP" NOT NULL ENABLE,
	"OPS_LEAD" VARCHAR2(50) COLLATE "USING_NLS_COMP" NOT NULL ENABLE,
	"DELEGATE_USER" VARCHAR2(50) COLLATE "USING_NLS_COMP",
	"IS_CONFIDENTIAL" VARCHAR2(1) COLLATE "USING_NLS_COMP" DEFAULT 'N' NOT NULL ENABLE,
	"TOTAL_COST" NUMBER(14,2) DEFAULT 0,
	"TOTAL_PRICE" NUMBER(14,2) DEFAULT 0,
	"MARGIN_PCT" NUMBER(6,2) DEFAULT 25.00,
	"MARKUP_PCT" NUMBER(6,2) DEFAULT 33.33,
	"CREATED_BY" VARCHAR2(50) COLLATE "USING_NLS_COMP" DEFAULT USER NOT NULL ENABLE,
	"CREATED_AT" TIMESTAMP (6) WITH LOCAL TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL ENABLE,
	"UPDATED_BY" VARCHAR2(50) COLLATE "USING_NLS_COMP" DEFAULT USER NOT NULL ENABLE,
	"UPDATED_AT" TIMESTAMP (6) WITH LOCAL TIME ZONE DEFAULT CURRENT_TIMESTAMP NOT NULL ENABLE,
	"BUDGET_AMOUNT" NUMBER(14,2) GENERATED ALWAYS AS ("TOTAL_PRICE"+0) VIRTUAL ,
	"TARGET_MARGIN_PCT" NUMBER(6,2) GENERATED ALWAYS AS ("MARGIN_PCT"+0) VIRTUAL ,
	"TENDER_TITLE" VARCHAR2(800) COLLATE "USING_NLS_COMP" GENERATED ALWAYS AS (SUBSTR("PROJECT_TITLE",1,200)) VIRTUAL ,
	"STAGE" VARCHAR2(120) COLLATE "USING_NLS_COMP" GENERATED ALWAYS AS (SUBSTR("CURRENT_STAGE",1,30)) VIRTUAL ,
	"CURRENCY_CODE" VARCHAR2(20) COLLATE "USING_NLS_COMP" GENERATED ALWAYS AS (SUBSTR("PRIMARY_CURRENCY",1,5)) VIRTUAL ,
	"DEAL_PROGRESSION" VARCHAR2(30) COLLATE "USING_NLS_COMP" DEFAULT 'IN_PROGRESS',
	"DEAL_VALUE" NUMBER(14,2),
	"DEAL_WON_DATE" DATE,
	 CHECK (office IN ('SG', 'JKT')) ENABLE,
	 CHECK (status IN ('ACTIVE', 'BLOCKED', 'CHANGES_REQUESTED', 'ON_HOLD', 'RELEASED', 'ARCHIVED')) ENABLE,
	 CHECK (primary_currency IN ('SGD', 'IDR', 'USD')) ENABLE,
	 CHECK (is_confidential IN ('Y', 'N')) ENABLE,
	 PRIMARY KEY ("TENDER_ID")
  USING INDEX  ENABLE,
	 UNIQUE ("TENDER_CODE")
  USING INDEX  ENABLE
