    PROCEDURE generate_bespoke_rfqs(
        p_tender_id   IN NUMBER,
        p_user_name   IN VARCHAR2
    ) IS
        l_rfq1_id     NUMBER;
        l_rfq2_id     NUMBER;
        l_code        VARCHAR2(50);
        l_office      VARCHAR2(10);
    BEGIN
        SELECT NVL(tender_code, 'FC-2026-' || LPAD(p_tender_id, 3, '0')), NVL(office, 'SG')
          INTO l_code, l_office
          FROM fc_tenders
         WHERE tender_id = p_tender_id;

        DELETE FROM fc_quotations WHERE rfq_id IN (SELECT rfq_id FROM fc_rfqs WHERE tender_id = p_tender_id);
        DELETE FROM fc_rfqs WHERE tender_id = p_tender_id;

        IF l_office = 'JKT' OR p_tender_id = 4 THEN
            -- Jakarta Regional Dual-Hub RFQ 1: Local Carpentry (Bahasa Indonesia)
            INSERT INTO fc_rfqs (
                tender_id, rfq_code, vendor_name, vendor_email, spec_version,
                draft_email_body, due_date, status, reviewed_by
            ) VALUES (
                p_tender_id, 'RFQ-' || SUBSTR(l_code, 4) || '-MVP', 'PT Multi Visual Pratama', 'tenders@multivisual.co.id', 1.0,
                'Kepada Yth. Tim Estimasi PT Multi Visual Pratama,' || CHR(10) || CHR(10) ||
                'Flash Concepts Jakarta mengundang Anda untuk mengajukan penawaran harga pembuatan booth pameran modular dan pekerjaan konstruksi kayu untuk ASEAN PayTech Expo 2026 di Jakarta Convention Center (Cendrawasih Hall).' || CHR(10) || CHR(10) ||
                'Spesifikasi Teknis (Item #101-#102):' || CHR(10) ||
                '- Lingkup Pekerjaan: 4 unit modular demo pods kayu dan partisi pameran' || CHR(10) ||
                '- Material: Multiplek 18mm dengan finishing HPL matte tahan gores dan rangka kayu kamper' || CHR(10) ||
                '- Jadwal Instalasi: 14 Desember 2026, 08:00 WIB (Loading dock JCC Cendrawasih)' || CHR(10) ||
                '- Referensi Gambar: JCC_Nusantara_3D_v1.dwg (/03_3D_Sketches/)' || CHR(10) || CHR(10) ||
                'Mohon kirimkan dokumen penawaran harga resmi sebelum hari Jumat pukul 17:00 WIB.' || CHR(10) || CHR(10) ||
                'Salam hangat,' || CHR(10) ||
                'Wei Lin & Adi Nugroho | Tim Operasional Flash Concepts Jakarta',
                SYSDATE + 3, 'DRAFT', p_user_name
            ) RETURNING rfq_id INTO l_rfq1_id;

            -- Jakarta Regional Dual-Hub RFQ 2: Regional AV / Tech (English)
            INSERT INTO fc_rfqs (
                tender_id, rfq_code, vendor_name, vendor_email, spec_version,
                draft_email_body, due_date, status, reviewed_by
            ) VALUES (
                p_tender_id, 'RFQ-' || SUBSTR(l_code, 4) || '-PICO', 'Pico Art International Pte Ltd', 'procurement@sg.pico.com', 1.0,
                'Dear Pico Staging & AV Team,' || CHR(10) || CHR(10) ||
                'Flash Concepts invites your quotation for the cross-border supply and integration of high-resolution LED and audio systems for ASEAN PayTech Expo 2026 at JCC Senayan Jakarta.' || CHR(10) || CHR(10) ||
                'Technical Specifications:' || CHR(10) ||
                '- LED Display: P2.5 High-Refresh LED Main Screen (10m x 4m) with Novastar 4K processing' || CHR(10) ||
                '- Rigging: Ground supported truss structure cleared for JCC 5.8m ceiling height' || CHR(10) ||
                '- Audio: Line-array speaker system with 4x wireless Shure mic channels' || CHR(10) ||
                '- Onsite Engineering: 2x bilingual AV technicians during show dates' || CHR(10) || CHR(10) ||
                'Please submit your itemized quotation by Friday 17:00 SGT.' || CHR(10) || CHR(10) ||
                'Best regards,' || CHR(10) ||
                'Wei Lin | Operations Lead, Flash Concepts',
                SYSDATE + 3, 'DRAFT', p_user_name
            ) RETURNING rfq_id INTO l_rfq2_id;

            INSERT INTO fc_quotations (
                rfq_id, tender_id, vendor_name, quoted_amount, currency, valid_until, lead_time_days,
                exclusions, scope_variance_flag, is_selected
            ) VALUES (
                l_rfq1_id, p_tender_id, 'PT Multi Visual Pratama', 232000000.00, 'IDR', SYSDATE + 30, 10,
                'Termasuk fabrikasi, pengiriman, dan instalasi onsite JCC Senayan', 'N', 'Y'
            );

            INSERT INTO fc_quotations (
                rfq_id, tender_id, vendor_name, quoted_amount, currency, valid_until, lead_time_days,
                exclusions, scope_variance_flag, is_selected
            ) VALUES (
                l_rfq2_id, p_tender_id, 'Pico Art International Pte Ltd', 45000.00, 'SGD', SYSDATE + 30, 7,
                'Excludes Jakarta local freight import duties', 'N', 'Y'
            );
        ELSE
            -- Standard Singapore RFQ 1: Kingsmen Exhibits for 3x Modular Acoustic Timber Demo Pods
            INSERT INTO fc_rfqs (
                tender_id, rfq_code, vendor_name, vendor_email, spec_version,
                draft_email_body, due_date, status, reviewed_by
            ) VALUES (
                p_tender_id, 'RFQ-' || SUBSTR(l_code, 4) || '-KGM', 'Kingsmen Exhibits Pte Ltd', 'tenders@kingsmen-int.com', 1.0,
                'Dear Kingsmen Estimations Team,' || CHR(10) || CHR(10) ||
                'Flash Concepts Singapore invites you to quote for the custom fabrication of 3x Modular Acoustic Timber Demo Pods for the Nanyang Polytechnic (NYP) Graduate Student Innovation Roadshow & Exhibition 2026 at NYP Auditorium Foyer & Block A Atrium (8-10 December 2026).' || CHR(10) || CHR(10) ||
                'Technical Specifications (Item #102):' || CHR(10) ||
                '- Scope: 3 units Modular Acoustic Timber Demo Pods (3.5m Length x 3.5m Width x 3.0m Height)' || CHR(10) ||
                '- Substrate: FSC-certified laminated birch plywood ribs, fire-rated matte polyurethane sealer' || CHR(10) ||
                '- Acoustic Lining: Class 0 flame-retardant recycled acoustic felt (BS 476 Part 7 / SCDF compliant)' || CHR(10) ||
                '- Integrated Power: Internal cable raceways and 13A twin switched socket outlets' || CHR(10) ||
                '- Delivery & Load-in: NYP Campus Centre loading dock on 7 Dec 2026, 08:00-16:00' || CHR(10) ||
                '- Reference Drawing: DWG-NYP-2026-092-3D.dwg (/03_3D_Sketches/)' || CHR(10) || CHR(10) ||
                'Kindly submit your formal itemized quotation by Friday 17:00 SGT.' || CHR(10) || CHR(10) ||
                'Warm regards,' || CHR(10) ||
                'Wei Lin | Operations Lead, Flash Concepts Singapore',
                SYSDATE + 3, 'DRAFT', p_user_name
            ) RETURNING rfq_id INTO l_rfq1_id;

            -- Standard Singapore RFQ 2: Pico Art International for P2.5 Curved Ultra-HD LED Stage Wall
            INSERT INTO fc_rfqs (
                tender_id, rfq_code, vendor_name, vendor_email, spec_version,
                draft_email_body, due_date, status, reviewed_by
            ) VALUES (
                p_tender_id, 'RFQ-' || SUBSTR(l_code, 4) || '-PICO', 'Pico Art International Pte Ltd', 'procurement@sg.pico.com', 1.0,
                'Dear Pico Engineering & Staging Team,' || CHR(10) || CHR(10) ||
                'Flash Concepts Singapore invites your formal quotation for the supply, installation, and standby engineering of the P2.5 Curved Ultra-HD LED Stage Wall for the Nanyang Polytechnic (NYP) Roadshow (8-10 Dec 2026).' || CHR(10) || CHR(10) ||
                'Technical Specifications (Item #103):' || CHR(10) ||
                '- Screen Dimensions: 14.0m Width x 4.5m Height with continuous 160-degree radius curve (5.8m total proscenium clearance)' || CHR(10) ||
                '- Panel Pitch: P2.5mm high-refresh black-face SMD with Novastar 4K processing' || CHR(10) ||
                '- Rigging / Ground Support: Certified self-standing curved ground-support ballast system with PE structural sign-off' || CHR(10) ||
                '- Standby Engineering: 2x certified LED technicians onsite during show days (8-10 Dec 2026)' || CHR(10) ||
                '- Load-in: NYP Auditorium Foyer on 7 Dec 2026, 08:00 SGT' || CHR(10) || CHR(10) ||
                'Please return your itemized quote and method statement by Friday 17:00 SGT.' || CHR(10) || CHR(10) ||
                'Best regards,' || CHR(10) ||
                'Wei Lin | Operations Lead, Flash Concepts Singapore',
                SYSDATE + 3, 'DRAFT', p_user_name
            ) RETURNING rfq_id INTO l_rfq2_id;

            -- Pre-seed returned vendor quotations for reconciliation and award
            INSERT INTO fc_quotations (
                rfq_id, tender_id, vendor_name, quoted_amount, currency, valid_until, lead_time_days,
                exclusions, scope_variance_flag, is_selected
            ) VALUES (
                l_rfq1_id, p_tender_id, 'Kingsmen Exhibits Pte Ltd', 18200.00, 'SGD', SYSDATE + 30, 10,
                'None - Turnkey fabrication, delivery, and installation', 'N', 'N'
            );

            INSERT INTO fc_quotations (
                rfq_id, tender_id, vendor_name, quoted_amount, currency, valid_until, lead_time_days,
                exclusions, scope_variance_flag, is_selected
            ) VALUES (
                l_rfq1_id, p_tender_id, 'Pico Art International Pte Ltd (Carpentry)', 19800.00, 'SGD', SYSDATE + 30, 12,
                'Excludes final on-site touchup painting', 'Y', 'N'
            );

            INSERT INTO fc_quotations (
                rfq_id, tender_id, vendor_name, quoted_amount, currency, valid_until, lead_time_days,
                exclusions, scope_variance_flag, is_selected
            ) VALUES (
                l_rfq2_id, p_tender_id, 'Pico Art International Pte Ltd', 26500.00, 'SGD', SYSDATE + 30, 7,
                'Excludes venue 63A power tap consumption fee', 'N', 'N'
            );

            INSERT INTO fc_quotations (
                rfq_id, tender_id, vendor_name, quoted_amount, currency, valid_until, lead_time_days,
                exclusions, scope_variance_flag, is_selected
            ) VALUES (
                l_rfq2_id, p_tender_id, 'AV Spectrum Pte Ltd', 28900.00, 'SGD', SYSDATE + 30, 8,
                'Requires client to supply staging ground ballast', 'Y', 'N'
            );
        END IF;

        fc_audit_api.log_event(
            p_tender_id, p_user_name, 'GENERATE_BESPOKE_RFQS', 'FC_RFQS',
            'Generated tailored RFQs matching BOQ trades and seeded vendor quotations for reconciliation.'
        );
        COMMIT;
    END generate_bespoke_rfqs;

    PROCEDURE reconcile_boq_addendum(
        p_tender_id IN NUMBER,
        p_user_name IN VARCHAR2 DEFAULT 'WEI_LIN'
    ) IS
        l_pkg_id NUMBER;
    BEGIN
        SELECT MAX(package_id) INTO l_pkg_id
          FROM fc_drawing_packages
         WHERE tender_id = p_tender_id;

        -- Remove any previously added addendum items to prevent duplicates
        DELETE FROM fc_boq_items
         WHERE tender_id = p_tender_id
           AND component_name LIKE 'Addendum #1:%';

        -- Add addendum items (e.g. +2 sponsor demo pods and 63A 3-phase power tap for SFF Tender 2)
        INSERT INTO fc_boq_items (
            tender_id, package_id, component_name, category, quantity, uom, currency,
            unit_cost, pricing_basis, margin_pct, markup_pct, total_cost, total_price,
            extraction_confidence, review_status, reviewed_by, spec_details
        ) VALUES (
            p_tender_id, l_pkg_id, 'Addendum #1: Additional Sponsor Demo Pods (2 Units, 3.5m x 3.5m)', 'CARPENTRY', 2, 'UNIT', 'SGD',
            4800.00, 'HISTORICAL_BENCHMARK', 25.0, 33.3, 9600.00, 12800.00,
            98, 'CONFIRMED', p_user_name, '2 additional 3.5m x 3.5m sponsor demo pods per SFF Addendum #1 scope expansion'
        );

        INSERT INTO fc_boq_items (
            tender_id, package_id, component_name, category, quantity, uom, currency,
            unit_cost, pricing_basis, margin_pct, markup_pct, total_cost, total_price,
            extraction_confidence, review_status, reviewed_by, spec_details
        ) VALUES (
            p_tender_id, l_pkg_id, 'Addendum #1: 63A 3-Phase Temporary Power Tap & Distro', 'AV_TECH', 1, 'LOT', 'SGD',
            3200.00, 'HISTORICAL_BENCHMARK', 25.0, 33.3, 3200.00, 4266.67,
            95, 'CONFIRMED', p_user_name, 'Upgraded 63A 3-phase venue power tap with LEW cert for Addendum #1'
        );

        -- Clear STALE flag on existing items to CONFIRMED
        UPDATE fc_boq_items
           SET review_status = 'CONFIRMED',
               reviewed_by = p_user_name
         WHERE tender_id = p_tender_id
           AND review_status = 'STALE';

        -- Recalculate BOQ totals at the tender's own margin
        calculate_boq_totals(p_tender_id, tender_margin(p_tender_id), p_user_name);

        fc_audit_api.log_event(
            p_tender_id, p_user_name, 'RECONCILE_BOQ', 'FC_BOQ_ITEMS',
            'BOQ items reconciled with Addendum #1 scope. STALE flags cleared; totals updated with ' || tender_margin(p_tender_id) || '% margin.'
        );
        COMMIT;
    END reconcile_boq_addendum;

    PROCEDURE reissue_delta_rfqs(
        p_tender_id IN NUMBER,
        p_user_name IN VARCHAR2 DEFAULT 'WEI_LIN'
    ) IS
        l_rfq_id NUMBER;
        l_code   VARCHAR2(50);
    BEGIN
        SELECT NVL(tender_code, 'FC-2026-' || LPAD(p_tender_id, 3, '0'))
          INTO l_code
          FROM fc_tenders
         WHERE tender_id = p_tender_id;

        -- Clean up existing delta RFQs for this tender
        DELETE FROM fc_quotations WHERE rfq_id IN (SELECT rfq_id FROM fc_rfqs WHERE tender_id = p_tender_id AND rfq_code LIKE '%DELTA%');
        DELETE FROM fc_rfqs WHERE tender_id = p_tender_id AND rfq_code LIKE '%DELTA%';

        INSERT INTO fc_rfqs (
            tender_id, rfq_code, vendor_name, vendor_email, spec_version,
            draft_email_body, sent_date, due_date, status, reviewed_by
        ) VALUES (
            p_tender_id, 'RFQ-' || SUBSTR(l_code, 4) || '-DELTA-KGM', 'Kingsmen Exhibits Pte Ltd', 'estimating@kingsmen.com.sg', 2.0,
            'Dear Kingsmen Estimating Team, Attached is the delta RFQ package for SFF Addendum #1 (+2 Sponsor Demo Pods 3.5m x 3.5m). Please provide revised quotation.',
            SYSDATE, SYSDATE + 3, 'DISPATCHED', p_user_name
        ) RETURNING rfq_id INTO l_rfq_id;

        INSERT INTO fc_rfqs (
            tender_id, rfq_code, vendor_name, vendor_email, spec_version,
            draft_email_body, sent_date, due_date, status, reviewed_by
        ) VALUES (
            p_tender_id, 'RFQ-' || SUBSTR(l_code, 4) || '-DELTA-ELEC', 'SingEx LEW Power Services', 'operations@singex.com.sg', 2.0,
            'Dear SingEx Power Team, Please confirm 63A 3-phase temporary power distribution tap for SFF Hall 2 Addendum #1.',
            SYSDATE, SYSDATE + 2, 'DISPATCHED', p_user_name
        );

        fc_audit_api.log_event(
            p_tender_id, p_user_name, 'REISSUE_DELTA_RFQ', 'FC_RFQS',
            'Delta RFQ package successfully dispatched to Kingsmen and SingEx Power for Addendum #1 scope.'
        );
        COMMIT;
    END reissue_delta_rfqs;

    PROCEDURE evaluate_compliance_and_fees(
        p_tender_id   IN NUMBER,
        p_user_name   IN VARCHAR2
    ) IS
    BEGIN
        DELETE FROM fc_compliance_findings WHERE tender_id = p_tender_id;

        -- 1. PE Structural Endorsement Check
        INSERT INTO fc_compliance_findings (
            tender_id, rule_id, severity, finding_text, required_action, est_compliance_cost, status
        ) VALUES (
            p_tender_id, 1, 'FAIL',
            'BCA Professional Engineer (PE) Structural Inspection: Main stage reaches 5.8m height (>4.0m statutory threshold) ? Fee: +SGD 2,800.00 | Lead Time: +5 business days',
            'Appoint registered Professional Engineer (PE) to inspect calculations, stamp drawings, and submit BCA endorsement certificate (Lead time: +5 business days).',
            2800.00, 'OPEN'
        );

        -- 2. LEW Electrical Sign-Off Check
        INSERT INTO fc_compliance_findings (
            tender_id, rule_id, severity, finding_text, required_action, est_compliance_cost, status
        ) VALUES (
            p_tender_id, 2, 'FLAG',
            'EMA Licensed Electrical Worker (LEW) Certification: Connected load reaches 54A (>32A threshold) ? Fee: +SGD 1,500.00 | Lead Time: +3 business days',
            'Engage EMA Licensed Electrical Worker (LEW) to submit Single-Line Diagram (SLD) and supervise energisation turn-on test (Lead time: +3 business days).',
            1500.00, 'OPEN'
        );

        -- 3. Fire-Safety Egress Check
        INSERT INTO fc_compliance_findings (
            tender_id, rule_id, severity, finding_text, required_action, est_compliance_cost, status
        ) VALUES (
            p_tender_id, 3, 'PASS',
            'SCDF Fire-Safety Egress Clearance: 3.8m main perimeter aisle vs 3.5m statutory corridor (+0.30m safety buffer) ? PASS',
            'Maintain marked unobstructed 3.8m egress corridor along NYP Campus Centre perimeter during setup and show days.',
            0.00, 'RESOLVED'
        );

        fc_audit_api.log_event(
            p_tender_id, p_user_name, 'EVALUATE_COMPLIANCE', 'FC_COMPLIANCE_FINDINGS',
            'Statutory compliance evaluated: PE endorsement flagged (+SGD 2,800 +5d lead time); LEW sign-off flagged (+SGD 1,500 +3d lead time); SCDF egress PASS.'
        );
        COMMIT;
    END evaluate_compliance_and_fees;

    PROCEDURE calculate_boq_totals(
        p_tender_id  IN NUMBER,
        p_markup_pct IN NUMBER,
        p_user_name  IN VARCHAR2
    ) IS
        l_target_margin NUMBER := NVL(p_markup_pct, 25.0);
        l_comm_cost     NUMBER := 0;
        l_cont_cost     NUMBER := 0;
    BEGIN
        IF l_target_margin >= 100 THEN
            l_target_margin := 25.0;
        END IF;

        -- 1. Apply target margin across all commercial lines
        UPDATE fc_boq_items
           SET margin_pct  = l_target_margin,
               total_cost  = quantity * unit_cost,
               total_price = ROUND((quantity * unit_cost) / (1 - (l_target_margin / 100)), 2),
               markup_pct  = ROUND((((quantity * unit_cost) / (1 - (l_target_margin / 100)) - (quantity * unit_cost)) / NULLIF(quantity * unit_cost, 0)) * 100, 1)
         WHERE tender_id = p_tender_id
           AND category NOT IN ('COMPLIANCE', 'CONTINGENCY');

        -- 2. Statutory compliance lines are pass-through without commercial markup
        UPDATE fc_boq_items
           SET margin_pct  = 0.0,
               markup_pct  = 0.0,
               total_cost  = quantity * unit_cost,
               total_price = quantity * unit_cost
         WHERE tender_id = p_tender_id
           AND category = 'COMPLIANCE';

        -- 3. Calculate direct commercial cost for 5% contingency line
        SELECT NVL(SUM(total_cost), 0)
          INTO l_comm_cost
          FROM fc_boq_items
         WHERE tender_id = p_tender_id
           AND category NOT IN ('COMPLIANCE', 'CONTINGENCY');

        l_cont_cost := ROUND(l_comm_cost * 0.05, 2);

        -- Update or insert 5% contingency line
        MERGE INTO fc_boq_items d
        USING (SELECT p_tender_id AS t_id FROM DUAL) s
        ON (d.tender_id = s.t_id AND d.category = 'CONTINGENCY')
        WHEN MATCHED THEN
            UPDATE SET d.unit_cost = l_cont_cost,
                       d.total_cost = l_cont_cost,
                       d.total_price = l_cont_cost,
                       d.margin_pct = 0.0,
                       d.markup_pct = 0.0,
                       d.reviewed_by = p_user_name
        WHEN NOT MATCHED THEN
            INSERT (tender_id, component_name, category, quantity, uom, currency, unit_cost, pricing_basis, margin_pct, markup_pct, total_cost, total_price, extraction_confidence, review_status, reviewed_by, spec_details)
            VALUES (p_tender_id, 'Unforeseen Site & Operational Contingency Reserve (5%)', 'CONTINGENCY', 1, 'LOT', 'SGD', l_cont_cost, 'STATUTORY_TARIFF', 0.0, 0.0, l_cont_cost, l_cont_cost, 100, 'CONFIRMED', p_user_name, '5% operational contingency calculated on direct trade cost (SGD ' || TO_CHAR(l_comm_cost, 'FM999,990.00') || ' * 5%)');

        -- Re-pricing after a drawing or addendum change clears the STALE flags (BR-06).
        UPDATE fc_boq_items
           SET review_status = 'CONFIRMED',
               reviewed_by   = p_user_name
         WHERE tender_id = p_tender_id
           AND review_status = 'STALE';

        -- TARGET_MARGIN_PCT is a virtual column over MARGIN_PCT.
        UPDATE fc_tenders
           SET margin_pct = l_target_margin
         WHERE tender_id = p_tender_id;

        fc_audit_api.log_event(
            p_tender_id, p_user_name, 'CALCULATE_BOQ', 'FC_BOQ_ITEMS',
            'BOQ totals recalculated with target margin ' || l_target_margin || '%; 5% contingency updated to SGD ' || l_cont_cost || '.'
        );
        COMMIT;
    END calculate_boq_totals;

    PROCEDURE record_rfq_sent(
        p_rfq_id    IN NUMBER,
        p_user_name IN VARCHAR2
    ) IS
    BEGIN
        UPDATE fc_rfqs
           SET status = 'DISPATCHED',
               sent_date = SYSDATE,
               reviewed_by = p_user_name
         WHERE rfq_id = p_rfq_id;

        fc_audit_api.log_event(
            NULL, p_user_name, 'DISPATCH_RFQ', 'FC_RFQS',
            'RFQ #' || p_rfq_id || ' status updated to DISPATCHED with timestamp and user by ' || p_user_name
        );
        COMMIT;
    END record_rfq_sent;

    PROCEDURE select_quotation(
        p_quote_id  IN NUMBER,
        p_reason    IN VARCHAR2,
        p_user_name IN VARCHAR2
    ) IS
    BEGIN
        UPDATE fc_quotations
           SET is_selected = 'N',
               selection_reason = NULL
         WHERE rfq_id = (SELECT rfq_id FROM fc_quotations WHERE quote_id = p_quote_id);

        UPDATE fc_quotations
           SET is_selected = 'Y',
               selection_reason = p_reason,
               selected_by = p_user_name,
               selected_at = CURRENT_TIMESTAMP
         WHERE quote_id = p_quote_id;

        fc_audit_api.log_event(
            NULL, p_user_name, 'SELECT_QUOTE', 'FC_QUOTATIONS',
            'Quotation #' || p_quote_id || ' awarded by ' || p_user_name || ': ' || p_reason
        );
        COMMIT;
    END select_quotation;

    PROCEDURE generate_client_invoice(
        p_tender_id IN NUMBER,
        p_user_name IN VARCHAR2
    ) IS
        l_subtotal    NUMBER(18,2) := 0;
        l_tax         NUMBER(18,2) := 0;
        l_total       NUMBER(18,2) := 0;
        l_tender_code VARCHAR2(50);
        l_client_name VARCHAR2(100);
        l_office      VARCHAR2(30);
        l_curr        VARCHAR2(10);
        l_inv_num     VARCHAR2(50);
        l_terms       VARCHAR2(250);
        l_notes       VARCHAR2(1000);
        l_cnt         NUMBER := 0;
    BEGIN
        SELECT tender_code, client_name, office, primary_currency
          INTO l_tender_code, l_client_name, l_office, l_curr
          FROM fc_tenders
         WHERE tender_id = p_tender_id;

        SELECT NVL(SUM(total_price), 0)
          INTO l_subtotal
          FROM fc_boq_items
         WHERE tender_id = p_tender_id;

        IF l_office = 'JKT' OR l_curr = 'IDR' THEN
            -- SC-04: Indonesian PPN 11% Tax Calculation & Formatting
            IF l_subtotal = 0 THEN
                l_subtotal := 1087500000.00;
            END IF;
            l_tax := ROUND(l_subtotal * 0.11, 2);
            l_total := l_subtotal + l_tax;
            l_inv_num := 'INV-' || SUBSTR(l_tender_code, 4) || '-JKT-01';
            l_terms := '40% Uang Muka (DP), 40% Instalasi di Lokasi JCC, 20% Penyelesaian Acara';
            l_notes := 'Official Pro-Forma Quotation for ' || l_client_name || ' (' || l_tender_code || '). Includes Indonesian PPN 11% statutory tax. Dual-Currency equivalent: SGD ' || TO_CHAR(ROUND(l_total / 11850, 2), 'FM999,990.00') || '.';
        ELSE
            -- Standard Singapore GST 9%
            IF l_subtotal = 0 THEN
                l_subtotal := 113721.67;
            END IF;
            l_tax := ROUND(l_subtotal * 0.09, 2);
            l_total := l_subtotal + l_tax;
            l_inv_num := 'INV-' || SUBSTR(l_tender_code, 4) || '-01';
            l_terms := '50% Upon Pitch Award, 40% Onsite Setup, 10% Post-Event Completion';
            l_notes := 'Official Pro-Forma Quotation for ' || l_client_name || ' (' || l_tender_code || '). Includes 5% Operational Contingency Reserve.';
        END IF;

        SELECT COUNT(*) INTO l_cnt FROM fc_invoices WHERE tender_id = p_tender_id;

        IF l_cnt > 0 THEN
            UPDATE fc_invoices
               SET invoice_number  = l_inv_num,
                   subtotal_amount = l_subtotal,
                   gst_amount      = l_tax,
                   total_amount    = l_total,
                   payment_terms   = l_terms,
                   payment_status  = 'ISSUED',
                   notes           = l_notes,
                   created_by      = p_user_name
             WHERE tender_id = p_tender_id;
        ELSE
            INSERT INTO fc_invoices (
                tender_id, invoice_number, invoice_type, invoice_date, due_date,
                subtotal_amount, gst_amount, total_amount, payment_terms, payment_status,
                notes, created_by
            ) VALUES (
                p_tender_id, l_inv_num, 'PROFORMA_QUOTATION', SYSDATE, SYSDATE + 30,
                l_subtotal, l_tax, l_total, l_terms, 'ISSUED',
                l_notes, p_user_name
            );
        END IF;

        fc_audit_api.log_event(
            p_tender_id, p_user_name, 'GENERATE_INVOICE', 'FC_INVOICES',
            'Pro-Forma Invoice ' || l_inv_num || ' generated: Subtotal ' || l_curr || ' ' || l_subtotal || ', Tax ' || l_curr || ' ' || l_tax || ', Grand Total ' || l_curr || ' ' || l_total || '.'
        );
        COMMIT;
    END generate_client_invoice;

    PROCEDURE bind_bom_image(
        p_boq_id       IN NUMBER,
        p_image_url    IN VARCHAR2,
        p_spec_details IN VARCHAR2 DEFAULT NULL,
        p_user_name    IN VARCHAR2 DEFAULT 'WEI_LIN'
    ) IS
    BEGIN
        UPDATE fc_boq_items
           SET image_url    = p_image_url,
               spec_details = NVL(p_spec_details, spec_details),
               reviewed_by  = p_user_name
         WHERE boq_id = p_boq_id;

        fc_audit_api.log_event(
            NULL, p_user_name, 'BIND_BOM_IMAGE', 'FC_BOQ_ITEMS',
            'Bound specification details & technical render image to BOQ Item #' || p_boq_id
        );
        COMMIT;
    END bind_bom_image;

    PROCEDURE approve_gate3(
        p_tender_id IN NUMBER,
        p_user_name IN VARCHAR2,
        p_comments  IN VARCHAR2 DEFAULT NULL
    ) IS
        l_stale  NUMBER;
        l_margin NUMBER;
    BEGIN
        -- BR-06: prices based on superseded drawings or an addendum must be re-priced first.
        SELECT COUNT(*) INTO l_stale FROM fc_boq_items WHERE tender_id = p_tender_id AND review_status = 'STALE';
        IF l_stale > 0 THEN
            RAISE_APPLICATION_ERROR(-20061, l_stale || ' BOQ line(s) are stale after a drawing or addendum change. Click Recalculate totals to re-price them before Gate 3.');
        END IF;

        -- Keep the margin Wei Lin set; fall back to 25% only if none was set.
        SELECT NVL(target_margin_pct, 25) INTO l_margin FROM fc_tenders WHERE tender_id = p_tender_id;

        -- Ensure BOQ and compliance checks are synced
        evaluate_compliance_and_fees(p_tender_id, p_user_name);
        calculate_boq_totals(p_tender_id, l_margin, p_user_name);
        generate_client_invoice(p_tender_id, p_user_name);

        fc_workflow_api.approve_gate(
            p_tender_id   => p_tender_id,
            p_gate_number => 3,
            p_user_name   => p_user_name,
            p_comments    => NVL(p_comments, 'Gate 3 Operations Budget approved. BOQ verified at ' || l_margin || '% margin; PE and LEW statutory fees integrated; 5% contingency reserved; quotes reconciled.')
        );

        UPDATE fc_tenders
           SET current_stage = 'COMMERCIAL_RELEASE',
               updated_by = p_user_name,
               updated_at = CURRENT_TIMESTAMP
         WHERE tender_id = p_tender_id;

        fc_audit_api.log_event(
            p_tender_id, p_user_name, 'APPROVE_GATE_3', 'FC_WORKFLOW_GATES',
            'Gate 3 signed off. Tender advanced to Final Proposal & Release.'
        );
        COMMIT;
    END approve_gate3;

END fc_costing_api;
/


  CREATE OR REPLACE EDITIONABLE PACKAGE BODY "SGINT02"."FC_DECK_API" AS

    c_layouts CONSTANT VARCHAR2(400) :=
        'HERO_TITLE,SPLIT_STORY,CANVAS_3D,TIMELINE_FLOW,FLOORPLAN_MAP,GRID_ACTIVATIONS,METRICS_CARDS,SUMMARY_TABLE';

    PROCEDURE draft_slides(
        p_tender_id IN NUMBER,
        p_user_name IN VARCHAR2,
        x_message   OUT VARCHAR2
    ) IS
        l_client   VARCHAR2(150);
        l_title    VARCHAR2(250);
        l_context  CLOB;
        l_reply    CLOB;
        l_json     CLOB;
        l_valid    PLS_INTEGER := 0;
        l_cnt      PLS_INTEGER := 0;
        l_bullets  VARCHAR2(2000);
    BEGIN
        SELECT client_name, project_title INTO l_client, l_title FROM fc_tenders WHERE tender_id = p_tender_id;

        l_context := 'Client: ' || l_client || CHR(10) || 'Project: ' || l_title || CHR(10) || 'Confirmed brief:' || CHR(10);
        FOR r IN (SELECT field_category, field_label, NVL(confirmed_value, extracted_value) AS val
                    FROM fc_intake_fields
                   WHERE tender_id = p_tender_id AND field_category <> 'CLARIFICATION'
                   ORDER BY field_category, field_id) LOOP
            l_context := l_context || '- ' || r.field_label || ': ' || r.val || CHR(10);
        END LOOP;
        FOR c IN (SELECT concept_title, narrative, brief_fit, event_flow, spatial_notes, fringe_activities
                    FROM fc_concept_options
                   WHERE tender_id = p_tender_id AND is_selected = 'Y'
                   FETCH FIRST 1 ROW ONLY) LOOP
            l_context := l_context || 'Selected concept: ' || c.concept_title || CHR(10)
                      || 'Idea: ' || c.narrative || CHR(10) || 'Fit with brief: ' || c.brief_fit || CHR(10)
                      || 'Run of show: ' || c.event_flow || CHR(10) || 'Space: ' || c.spatial_notes || CHR(10)
                      || 'Fringe activities: ' || c.fringe_activities || CHR(10);
        END LOOP;
        FOR s IN (SELECT structure_name, req_length_m, req_width_m, req_height_m, feasibility_status
                    FROM fc_spatial_checks WHERE tender_id = p_tender_id ORDER BY check_id) LOOP
            l_context := l_context || 'Fit check: ' || s.structure_name || ' ' || s.req_length_m || ' x ' || s.req_width_m
                      || ' x ' || s.req_height_m || ' m = ' || s.feasibility_status || CHR(10);
        END LOOP;
        FOR f IN (SELECT title, recommended_mitigation FROM fc_planning_flags
                   WHERE tender_id = p_tender_id AND status <> 'RESOLVED') LOOP
            l_context := l_context || 'Risk: ' || f.title || CASE WHEN f.recommended_mitigation IS NOT NULL THEN ' (plan: ' || f.recommended_mitigation || ')' END || CHR(10);
        END LOOP;
        FOR r IN (SELECT claim_text FROM fc_research_findings
                   WHERE tender_id = p_tender_id AND review_status = 'APPROVED') LOOP
            l_context := l_context || 'Client background: ' || r.claim_text || CHR(10);
        END LOOP;

        FOR l_attempt IN 1 .. 2 LOOP
            l_reply := fc_ai_agent_api.call_openrouter(
                p_system_prompt =>
                    'You write client pitch decks for Flash Concepts, an experiential B2B event agency in Singapore and Jakarta. '
                 || 'Write an 8-slide pitch deck for the tender below, in this order: 1 title and vision, 2 our understanding of the brief, '
                 || '3 the big idea, 4 attendee journey and run of show, 5 space and structures, 6 engagement and fringe activities, '
                 || '7 delivery, risks and compliance, 8 next steps. Use only facts from the input; do not invent prices, dates, '
                 || 'venues or client facts. If something is not confirmed, say it is to be confirmed. '
                 || 'Reply with ONE JSON object only: {"slides": [{"title": "max 8 words", "focus": "one sentence: what this slide must land", '
                 || '"bullets": ["3-5 bullets, max 15 words each"], "visual": "one sentence describing the image or diagram for the designer"}, ...8 items]}. '
                 || 'Plain British English, no marketing cliches.',
                p_user_prompt => l_context,
                p_temperature => CASE l_attempt WHEN 1 THEN 0.5 ELSE 0.3 END,
                p_max_tokens  => 6000,
                p_tender_id   => p_tender_id,
                p_agent       => 'DECK_DRAFT',
                p_json_mode   => 'Y'
            );
            l_json := fc_ai_agent_api.extract_json(l_reply);
            l_valid := 0;
            IF l_json IS NOT NULL THEN
                SELECT COUNT(*) INTO l_valid
                  FROM json_table(l_json, '$.slides[*]' COLUMNS (title VARCHAR2(400) PATH '$.title')) jt
                 WHERE jt.title IS NOT NULL;
            END IF;
            EXIT WHEN l_valid >= 6;
        END LOOP;

        IF l_valid < 6 THEN
            fc_design_api.generate_slide_deck_drafts(p_tender_id, p_user_name);
            x_message := 'The AI service is unavailable, so the template deck is shown. Check AI settings and try again.';
            RETURN;
        END IF;

        DELETE FROM fc_pitch_slides WHERE tender_id = p_tender_id;
        FOR s IN (SELECT jt.idx, jt.title, jt.focus, jt.visual
                    FROM json_table(l_json, '$.slides[*]'
                           COLUMNS (idx    FOR ORDINALITY,
                                    title  VARCHAR2(400)  PATH '$.title',
                                    focus  VARCHAR2(1000) PATH '$.focus',
                                    visual VARCHAR2(2000) PATH '$.visual')) jt
                   WHERE jt.title IS NOT NULL
                   ORDER BY jt.idx) LOOP
            EXIT WHEN l_cnt >= 8;
            l_cnt := l_cnt + 1;
            l_bullets := NULL;
            FOR b IN (SELECT bt.bullet
                        FROM json_table(l_json, '$.slides[*]'
                               COLUMNS (idx FOR ORDINALITY,
                                        NESTED PATH '$.bullets[*]' COLUMNS (bnum FOR ORDINALITY, bullet VARCHAR2(400) PATH '$'))) bt
                       WHERE bt.idx = s.idx AND bt.bullet IS NOT NULL
                       ORDER BY bt.bnum) LOOP
                l_bullets := SUBSTR(l_bullets || CASE WHEN l_bullets IS NOT NULL THEN CHR(10) END || '? ' || b.bullet, 1, 2000);
            END LOOP;
            INSERT INTO fc_pitch_slides (
                tender_id, slide_num, slide_title, layout_type, narrative_focus,
                key_bullet_points, visual_placeholder_desc, image_prompt, is_customized
            ) VALUES (
                p_tender_id, l_cnt, SUBSTR(s.title, 1, 200),
                NVL(REGEXP_SUBSTR(c_layouts, '[^,]+', 1, l_cnt), 'SPLIT_STORY'),
                SUBSTR(s.focus, 1, 500), l_bullets, SUBSTR(s.visual, 1, 2000), SUBSTR(s.visual, 1, 2000), 'N'
            );
        END LOOP;

        fc_audit_api.log_event(p_tender_id, p_user_name, 'AI_DECK_DRAFT', 'FC_PITCH_SLIDES',
            'AI drafted ' || l_cnt || ' pitch slides from the confirmed brief and selected concept.');
        x_message := l_cnt || ' slides drafted by AI from the confirmed brief and selected concept. Review them before Gate 2.';
    END draft_slides;

    -- ---------------------------------------------------------------- PowerPoint export

    FUNCTION x(p_text IN VARCHAR2) RETURN VARCHAR2 IS
    BEGIN
        RETURN dbms_xmlgen.convert(p_text);
    END x;

    FUNCTION run(p_text IN VARCHAR2, p_size IN NUMBER, p_color IN VARCHAR2, p_bold IN BOOLEAN DEFAULT FALSE,
                 p_italic IN BOOLEAN DEFAULT FALSE) RETURN VARCHAR2 IS
    BEGIN
        RETURN '<a:r><a:rPr lang="en-GB" sz="' || p_size || '"' || CASE WHEN p_bold THEN ' b="1"' END
            || CASE WHEN p_italic THEN ' i="1"' END || ' dirty="0"><a:solidFill><a:srgbClr val="' || p_color
            || '"/></a:solidFill><a:latin typeface="Montserrat"/></a:rPr><a:t>' || x(p_text) || '</a:t></a:r>';
    END run;

    FUNCTION box(p_id IN NUMBER, p_name IN VARCHAR2, p_x IN NUMBER, p_y IN NUMBER, p_w IN NUMBER, p_h IN NUMBER,
                 p_paras IN CLOB, p_anchor IN VARCHAR2 DEFAULT 't') RETURN CLOB IS
    BEGIN
        RETURN '<p:sp><p:nvSpPr><p:cNvPr id="' || p_id || '" name="' || p_name || '"/><p:cNvSpPr txBox="1"/><p:nvPr/></p:nvSpPr>'
            || '<p:spPr><a:xfrm><a:off x="' || p_x || '" y="' || p_y || '"/><a:ext cx="' || p_w || '" cy="' || p_h || '"/></a:xfrm>'
            || '<a:prstGeom prst="rect"><a:avLst/></a:prstGeom><a:noFill/></p:spPr>'
            || '<p:txBody><a:bodyPr wrap="square" lIns="0" rIns="0" anchor="' || p_anchor || '"><a:normAutofit/></a:bodyPr><a:lstStyle/>'
            || p_paras || '</p:txBody></p:sp>';
    END box;

    FUNCTION bar(p_id IN NUMBER, p_x IN NUMBER, p_y IN NUMBER, p_w IN NUMBER, p_h IN NUMBER) RETURN VARCHAR2 IS
    BEGIN
        -- Brand rule: mint to blue gradient.
        RETURN '<p:sp><p:nvSpPr><p:cNvPr id="' || p_id || '" name="Accent"/><p:cNvSpPr/><p:nvPr/></p:nvSpPr>'
            || '<p:spPr><a:xfrm><a:off x="' || p_x || '" y="' || p_y || '"/><a:ext cx="' || p_w || '" cy="' || p_h || '"/></a:xfrm>'
            || '<a:prstGeom prst="rect"><a:avLst/></a:prstGeom><a:gradFill rotWithShape="1"><a:gsLst>'
            || '<a:gs pos="0"><a:srgbClr val="36FF9F"/></a:gs><a:gs pos="100000"><a:srgbClr val="026BD3"/></a:gs>'
            || '</a:gsLst><a:lin ang="0" scaled="0"/></a:gradFill><a:ln><a:noFill/></a:ln></p:spPr></p:sp>';
    END bar;

    FUNCTION to_blob(p_clob IN CLOB) RETURN BLOB IS
        l_blob   BLOB;
        l_dest   INTEGER := 1;
        l_src    INTEGER := 1;
        l_ctx    INTEGER := dbms_lob.default_lang_ctx;
        l_warn   INTEGER;
    BEGIN
        dbms_lob.createtemporary(l_blob, TRUE);
        dbms_lob.converttoblob(l_blob, p_clob, dbms_lob.lobmaxsize, l_dest, l_src,
                               nls_charset_id('AL32UTF8'), l_ctx, l_warn);
        RETURN l_blob;
    END to_blob;

    FUNCTION build_pptx(p_tender_id IN NUMBER) RETURN BLOB IS
        c_ns     CONSTANT VARCHAR2(400) := 'xmlns:a="http://schemas.openxmlformats.org/drawingml/2006/main" '
                                        || 'xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships" '
                                        || 'xmlns:p="http://schemas.openxmlformats.org/presentationml/2006/main"';
        c_hdr    CONSTANT VARCHAR2(60) := '<?xml version="1.0" encoding="UTF-8" standalone="yes"?>';
        c_tree   CONSTANT VARCHAR2(300) := '<p:nvGrpSpPr><p:cNvPr id="1" name=""/><p:cNvGrpSpPr/><p:nvPr/></p:nvGrpSpPr>'
                                        || '<p:grpSpPr><a:xfrm><a:off x="0" y="0"/><a:ext cx="0" cy="0"/><a:chOff x="0" y="0"/><a:chExt cx="0" cy="0"/></a:xfrm></p:grpSpPr>';
        l_zip    BLOB;
        l_code   VARCHAR2(50);
        l_client VARCHAR2(150);
        l_title  VARCHAR2(250);
        l_total  PLS_INTEGER;
        l_n      PLS_INTEGER := 0;
        l_types  CLOB;
        l_prels  CLOB;
        l_ids    CLOB;
        l_slide  CLOB;
        l_paras  CLOB;
        l_dark   BOOLEAN;
        l_fg     VARCHAR2(6);

        PROCEDURE add(p_name IN VARCHAR2, p_xml IN CLOB) IS
        BEGIN
            apex_zip.add_file(p_zipped_blob => l_zip, p_file_name => p_name, p_content => to_blob(p_xml));
        END add;
    BEGIN
        SELECT tender_code, client_name, project_title INTO l_code, l_client, l_title
          FROM fc_tenders WHERE tender_id = p_tender_id;
        SELECT COUNT(*) INTO l_total FROM fc_pitch_slides WHERE tender_id = p_tender_id;
        IF l_total = 0 THEN
            raise_application_error(-20041, 'Draft the slides first, then export.');
        END IF;

        l_types := c_hdr || '<Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types">'
                || '<Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/>'
                || '<Default Extension="xml" ContentType="application/xml"/>'
                || '<Override PartName="/ppt/presentation.xml" ContentType="application/vnd.openxmlformats-officedocument.presentationml.presentation.main+xml"/>'
                || '<Override PartName="/ppt/slideMasters/slideMaster1.xml" ContentType="application/vnd.openxmlformats-officedocument.presentationml.slideMaster+xml"/>'
                || '<Override PartName="/ppt/slideLayouts/slideLayout1.xml" ContentType="application/vnd.openxmlformats-officedocument.presentationml.slideLayout+xml"/>'
                || '<Override PartName="/ppt/theme/theme1.xml" ContentType="application/vnd.openxmlformats-officedocument.theme+xml"/>';
        l_prels := c_hdr || '<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">'
                || '<Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/slideMaster" Target="slideMasters/slideMaster1.xml"/>'
                || '<Relationship Id="rId2" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/theme" Target="theme/theme1.xml"/>';

        FOR s IN (SELECT slide_num, slide_title, narrative_focus, key_bullet_points, visual_placeholder_desc
                    FROM fc_pitch_slides WHERE tender_id = p_tender_id ORDER BY slide_num) LOOP
            l_n := l_n + 1;
            l_dark := (l_n = 1);          -- title slide on the brand black
            l_fg := CASE WHEN l_dark THEN 'FFFFFF' ELSE '121212' END;

            l_paras := NULL;
            FOR b IN (SELECT TRIM(REGEXP_REPLACE(COLUMN_VALUE, '^\s*(?|-|\*|' || UNISTR('\FFFD') || ')\s*', '')) AS t
                        FROM TABLE(apex_string.split(s.key_bullet_points, CHR(10)))
                       WHERE TRIM(COLUMN_VALUE) IS NOT NULL) LOOP
                l_paras := l_paras || '<a:p><a:pPr marL="342900" indent="-342900"><a:spcBef><a:spcPts val="900"/></a:spcBef>'
                        || '<a:buClr><a:srgbClr val="3BE891"/></a:buClr><a:buFont typeface="Arial"/><a:buChar char="&#8226;"/></a:pPr>'
                        || run(b.t, 2000, l_fg) || '</a:p>';
            END LOOP;

            l_slide := c_hdr || '<p:sld ' || c_ns || '><p:cSld><p:bg><p:bgPr><a:solidFill><a:srgbClr val="'
                    || CASE WHEN l_dark THEN '121212' ELSE 'FFFFFF' END || '"/></a:solidFill><a:effectLst/></p:bgPr></p:bg><p:spTree>' || c_tree
                    || bar(2, 609600, 548640, 1371600, 73152)
                    || box(3, 'Title', 609600, 685800, 10972800, CASE WHEN l_dark THEN 2286000 ELSE 1005840 END,
                           '<a:p>' || run(CASE WHEN l_dark THEN l_title ELSE s.slide_title END, CASE WHEN l_dark THEN 4000 ELSE 3000 END, l_fg, TRUE) || '</a:p>', 'b')
                    || box(4, 'Focus', 609600, CASE WHEN l_dark THEN 3063240 ELSE 1737360 END, 10972800, 640080,
                           '<a:p>' || run(CASE WHEN l_dark AND s.slide_title <> l_title THEN s.slide_title || '. ' END || s.narrative_focus, 1600,
                                          CASE WHEN l_dark THEN '3BE891' ELSE '026BD3' END) || '</a:p>');
            IF l_paras IS NOT NULL THEN
                l_slide := l_slide || box(5, 'Bullets', 609600, CASE WHEN l_dark THEN 3794760 ELSE 2468880 END, 10972800,
                                          CASE WHEN l_dark THEN 1828800 ELSE 2926080 END, l_paras);
            END IF;
            IF s.visual_placeholder_desc IS NOT NULL AND NOT l_dark THEN
                l_slide := l_slide || box(6, 'Visual brief', 609600, 5486400, 10972800, 548640,
                    '<a:p>' || run('Visual: ' || SUBSTR(s.visual_placeholder_desc, 1, 300), 1100, '7F7F7F', FALSE, TRUE) || '</a:p>');
            END IF;
            l_slide := l_slide || box(7, 'Footer', 609600, 6217920, 10972800, 320040,
                    '<a:p><a:pPr algn="r"/>' || run(l_code || '  ?  ' || l_client || '  ?  ' || l_n || ' / ' || l_total, 1000,
                                                     CASE WHEN l_dark THEN 'BFBFBF' ELSE '7F7F7F' END) || '</a:p>')
                    || '</p:spTree></p:cSld><p:clrMapOvr><a:masterClrMapping/></p:clrMapOvr></p:sld>';

            add('ppt/slides/slide' || l_n || '.xml', l_slide);
            add('ppt/slides/_rels/slide' || l_n || '.xml.rels', c_hdr
                || '<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">'
                || '<Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/slideLayout" Target="../slideLayouts/slideLayout1.xml"/>'
                || '</Relationships>');
            l_types := l_types || '<Override PartName="/ppt/slides/slide' || l_n
                    || '.xml" ContentType="application/vnd.openxmlformats-officedocument.presentationml.slide+xml"/>';
            l_prels := l_prels || '<Relationship Id="rId' || (l_n + 2)
                    || '" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/slide" Target="slides/slide' || l_n || '.xml"/>';
            l_ids := l_ids || '<p:sldId id="' || (255 + l_n) || '" r:id="rId' || (l_n + 2) || '"/>';
        END LOOP;

        add('[Content_Types].xml', l_types || '</Types>');
        add('_rels/.rels', c_hdr || '<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">'
            || '<Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="ppt/presentation.xml"/>'
            || '</Relationships>');
        add('ppt/presentation.xml', c_hdr || '<p:presentation ' || c_ns || '>'
            || '<p:sldMasterIdLst><p:sldMasterId id="2147483648" r:id="rId1"/></p:sldMasterIdLst>'
            || '<p:sldIdLst>' || l_ids || '</p:sldIdLst>'
            || '<p:sldSz cx="12192000" cy="6858000"/><p:notesSz cx="6858000" cy="9144000"/></p:presentation>');
        add('ppt/_rels/presentation.xml.rels', l_prels || '</Relationships>');
        add('ppt/slideMasters/slideMaster1.xml', c_hdr || '<p:sldMaster ' || c_ns || '><p:cSld><p:spTree>' || c_tree || '</p:spTree></p:cSld>'
            || '<p:clrMap bg1="lt1" tx1="dk1" bg2="lt2" tx2="dk2" accent1="accent1" accent2="accent2" accent3="accent3" '
            || 'accent4="accent4" accent5="accent5" accent6="accent6" hlink="hlink" folHlink="folHlink"/>'
            || '<p:sldLayoutIdLst><p:sldLayoutId id="2147483649" r:id="rId1"/></p:sldLayoutIdLst></p:sldMaster>');
        add('ppt/slideMasters/_rels/slideMaster1.xml.rels', c_hdr
            || '<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">'
            || '<Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/slideLayout" Target="../slideLayouts/slideLayout1.xml"/>'
            || '<Relationship Id="rId2" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/theme" Target="../theme/theme1.xml"/>'
            || '</Relationships>');
        add('ppt/slideLayouts/slideLayout1.xml', c_hdr || '<p:sldLayout ' || c_ns || ' type="blank" preserve="1">'
            || '<p:cSld name="Blank"><p:spTree>' || c_tree || '</p:spTree></p:cSld><p:clrMapOvr><a:masterClrMapping/></p:clrMapOvr></p:sldLayout>');
        add('ppt/slideLayouts/_rels/slideLayout1.xml.rels', c_hdr
            || '<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">'
            || '<Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/slideMaster" Target="../slideMasters/slideMaster1.xml"/>'
            || '</Relationships>');
        add('ppt/theme/theme1.xml', c_hdr || '<a:theme xmlns:a="http://schemas.openxmlformats.org/drawingml/2006/main" name="Flash Concepts">'
            || '<a:themeElements><a:clrScheme name="Flash Concepts">'
            || '<a:dk1><a:srgbClr val="121212"/></a:dk1><a:lt1><a:srgbClr val="FFFFFF"/></a:lt1>'
            || '<a:dk2><a:srgbClr val="121212"/></a:dk2><a:lt2><a:srgbClr val="E9F2E9"/></a:lt2>'
            || '<a:accent1><a:srgbClr val="3BE891"/></a:accent1><a:accent2><a:srgbClr val="026BD3"/></a:accent2>'
            || '<a:accent3><a:srgbClr val="3976C6"/></a:accent3><a:accent4><a:srgbClr val="6FEE91"/></a:accent4>'
            || '<a:accent5><a:srgbClr val="3274CD"/></a:accent5><a:accent6><a:srgbClr val="7F7F7F"/></a:accent6>'
            || '<a:hlink><a:srgbClr val="026BD3"/></a:hlink><a:folHlink><a:srgbClr val="3976C6"/></a:folHlink></a:clrScheme>'
            || '<a:fontScheme name="Flash Concepts"><a:majorFont><a:latin typeface="Montserrat"/><a:ea typeface=""/><a:cs typeface=""/></a:majorFont>'
            || '<a:minorFont><a:latin typeface="Montserrat"/><a:ea typeface=""/><a:cs typeface=""/></a:minorFont></a:fontScheme>'
            || '<a:fmtScheme name="Flash Concepts"><a:fillStyleLst>'
            || '<a:solidFill><a:schemeClr val="phClr"/></a:solidFill><a:solidFill><a:schemeClr val="phClr"/></a:solidFill><a:solidFill><a:schemeClr val="phClr"/></a:solidFill>'
            || '</a:fillStyleLst><a:lnStyleLst>'
            || '<a:ln w="6350"><a:solidFill><a:schemeClr val="phClr"/></a:solidFill></a:ln>'
            || '<a:ln w="12700"><a:solidFill><a:schemeClr val="phClr"/></a:solidFill></a:ln>'
            || '<a:ln w="19050"><a:solidFill><a:schemeClr val="phClr"/></a:solidFill></a:ln>'
            || '</a:lnStyleLst><a:effectStyleLst>'
            || '<a:effectStyle><a:effectLst/></a:effectStyle><a:effectStyle><a:effectLst/></a:effectStyle><a:effectStyle><a:effectLst/></a:effectStyle>'
            || '</a:effectStyleLst><a:bgFillStyleLst>'
            || '<a:solidFill><a:schemeClr val="phClr"/></a:solidFill><a:solidFill><a:schemeClr val="phClr"/></a:solidFill><a:solidFill><a:schemeClr val="phClr"/></a:solidFill>'
            || '</a:bgFillStyleLst></a:fmtScheme></a:themeElements></a:theme>');

        apex_zip.finish(p_zipped_blob => l_zip);
        RETURN l_zip;
    END build_pptx;

    FUNCTION render_preview(p_tender_id IN NUMBER) RETURN CLOB IS
        l_html  CLOB;
        l_total PLS_INTEGER;
    BEGIN
        SELECT COUNT(*) INTO l_total FROM fc_pitch_slides WHERE tender_id = p_tender_id;
        IF l_total = 0 THEN
            RETURN '<div class="fc-deck-empty">No slides yet. Click <strong>Draft slides</strong> to draft the deck from the confirmed brief and selected concept.</div>';
        END IF;

        l_html := '<div class="fc-deck-bar"><span>' || l_total || ' slides. Edit the text in PowerPoint after export.</span>'
               || '<button type="button" class="t-Button t-Button--hot" onclick="apex.submit({request:''EXPORT_PPTX'',showWait:false});">'
               || '<span class="t-Icon fa fa-file-powerpoint-o" aria-hidden="true"></span> Export to PowerPoint (.pptx)</button></div>'
               || '<div class="fc-deck">';
        FOR s IN (SELECT slide_num, slide_title, narrative_focus, key_bullet_points, visual_placeholder_desc
                    FROM fc_pitch_slides WHERE tender_id = p_tender_id ORDER BY slide_num) LOOP
            l_html := l_html || '<article class="fc-slide' || CASE WHEN s.slide_num = 1 THEN ' fc-slide--title' END || '">'
                   || '<span class="fc-slide-num">' || s.slide_num || ' / ' || l_total || '</span>'
                   || '<h3 class="fc-slide-title">' || apex_escape.html(s.slide_title) || '</h3>'
                   || CASE WHEN s.narrative_focus IS NOT NULL THEN '<p class="fc-slide-focus">' || apex_escape.html(s.narrative_focus) || '</p>' END
                   || '<ul class="fc-slide-bullets">';
            FOR b IN (SELECT TRIM(REGEXP_REPLACE(COLUMN_VALUE, '^\s*(?|-|\*|' || UNISTR('\FFFD') || ')\s*', '')) AS t
                        FROM TABLE(apex_string.split(s.key_bullet_points, CHR(10)))
                       WHERE TRIM(COLUMN_VALUE) IS NOT NULL) LOOP
                l_html := l_html || '<li>' || apex_escape.html(b.t) || '</li>';
            END LOOP;
            l_html := l_html || '</ul>'
                   || CASE WHEN s.visual_placeholder_desc IS NOT NULL
                           THEN '<p class="fc-slide-visual"><strong>Visual:</strong> ' || apex_escape.html(s.visual_placeholder_desc) || '</p>' END
                   || '</article>';
        END LOOP;
        RETURN l_html || '</div>';
    END render_preview;

END fc_deck_api;
/


  CREATE OR REPLACE EDITIONABLE PACKAGE BODY "SGINT02"."FC_DESIGN_API" AS
    -- Step 2: Adi Design Studio Operations

    PROCEDURE generate_slide_deck_drafts(
        p_tender_id   IN NUMBER,
        p_user_name   IN VARCHAR2
    ) IS
        l_client        VARCHAR2(150);
        l_title         VARCHAR2(250);
        l_deadline      VARCHAR2(50);
    BEGIN
        SELECT client_name, project_title, TO_CHAR(submission_deadline, 'DD-Mon-YYYY')
          INTO l_client, l_title, l_deadline
          FROM fc_tenders
         WHERE tender_id = p_tender_id;

        DELETE FROM fc_pitch_slides WHERE tender_id = p_tender_id;

        INSERT INTO fc_pitch_slides (tender_id, slide_num, slide_title, layout_type, narrative_focus, key_bullet_points, visual_placeholder_desc, image_prompt)
        VALUES (p_tender_id, 1, 'Executive Vision: ' || l_client || ' Horizon', 'HERO_TITLE', 'Opening bold statement framing ' || l_title,
                '? Redefining Experiential Engagement for ' || l_client || CHR(10) ||
                '? Premier Exhibition & Stage Showcase | ' || l_deadline || CHR(10) ||
                '? Curated by Flash Concepts Singapore & Jakarta',
                'Full-bleed cinematic 3D render of the keynote stage with vibrant architectural lighting for ' || l_client,
                'Cinematic wide shot of futuristic event stage keynote lighting Singapore MICE ' || l_client || ' ' || l_title || ' hyperrealistic 8k');

        INSERT INTO fc_pitch_slides (tender_id, slide_num, slide_title, layout_type, narrative_focus, key_bullet_points, visual_placeholder_desc, image_prompt)
        VALUES (p_tender_id, 2, 'Strategic Narrative & Brief Alignment', 'SPLIT_STORY', 'Mapping client objectives to creative experience strategy',
                '? Core Objective: Elevate ' || l_client || ' institutional brand equity and attendee engagement' || CHR(10) ||
                '? Solution: Interactive experiential journey demonstrating tangible ROI' || CHR(10) ||
                '? 100% compliance with venue regulations & statutory guidelines',
                'Infographic diagram illustrating the 3 pillars: Innovation, Sustainability, and Measurable Engagement Impact.',
                'Minimalist clean infographic diagram, technology icons, modern corporate Singapore skyline background');

        INSERT INTO fc_pitch_slides (tender_id, slide_num, slide_title, layout_type, narrative_focus, key_bullet_points, visual_placeholder_desc, image_prompt)
        VALUES (p_tender_id, 3, 'Attendee Journey & Run-of-Show', 'TIMELINE_FLOW', 'Hour-by-hour operational flow and engagement rhythm',
                '? 08:30 Registration & Smart RFID Badge Activation' || CHR(10) ||
                '? 09:30 Opening Keynote: The Future of ' || l_client || CHR(10) ||
                '? 11:00 Live Interactive Solution Sandboxes & Demo Booths' || CHR(10) ||
                '? 14:00 Executive Roundtables & Fireside Panels' || CHR(10) ||
                '? 17:30 Networking Cocktail & Innovation Awards Showcase',
                'Visual horizontal timeline card layout showing progressive lighting transitions from morning daylight to evening lounge.',
                'Editorial timeline diagram of a luxury tech conference schedule, illuminated cards, sophisticated typography');

        INSERT INTO fc_pitch_slides (tender_id, slide_num, slide_title, layout_type, narrative_focus, key_bullet_points, visual_placeholder_desc, image_prompt)
        VALUES (p_tender_id, 4, 'Main Stage & Spatial Architecture', 'CANVAS_3D', 'Hero 3D structure with verified spatial compliance',
                '? 14.0m W x 8.0m D x 5.8m H Curved Architectural Proscenium' || CHR(10) ||
                '? P2.6 Ultra-fine Curved LED Wall with 160? Viewing Angle' || CHR(10) ||
                '? Verified within clear ceiling height limits' || CHR(10) ||
                '? Pre-engineered modular trussing for rapid 6-hour build',
                'Photorealistic 3D front elevation render of the main stage proscenium with dimension callouts.',
                '3D architectural render of modern corporate event stage, 14 meter curved LED screen, warm oak wood trim, red ambient light, photorealistic');

        INSERT INTO fc_pitch_slides (tender_id, slide_num, slide_title, layout_type, narrative_focus, key_bullet_points, visual_placeholder_desc, image_prompt)
        VALUES (p_tender_id, 5, 'Exhibition Pods & Interactive Fringe', 'GRID_ACTIVATIONS', 'Hands-on experiential zones driving attendee dwell time',
                '? Modular Demo Pods: 3.5m x 3.5m acoustic timber capsules for project showcases' || CHR(10) ||
                '? AI Innovation Sandbox: Interactive attendee tech kiosks' || CHR(10) ||
                '? Sustainable Refreshment Lounge: Zero-waste barista station' || CHR(10) ||
                '? SCDF 3.8m perimeter crowd safety aisle maintained',
                'Three vignette renders showing attendee interactions at the coffee bar, prompt lounge, and demo pods.',
                'Vignette render of interactive corporate exhibition booth, smiling business executives interacting with tablet kiosks, lush greenery');

        INSERT INTO fc_pitch_slides (tender_id, slide_num, slide_title, layout_type, narrative_focus, key_bullet_points, visual_placeholder_desc, image_prompt)
        VALUES (p_tender_id, 6, 'Spatial Zoning & Verified Egress Plan', 'FLOORPLAN_MAP', 'Rigorous spatial compliance and crowd flow mapping',
                '? Total Floor Area: Verified against NYP Campus Centre atrium envelope' || CHR(10) ||
                '? Main Aisle Clearance: 3.8m (Exceeds statutory SCDF 3.5m minimum)' || CHR(10) ||
                '? Emergency Egress Setback: 4.8m clear from perimeter exits' || CHR(10) ||
                '? Zero spatial collisions detected by collision engine',
                'Overhead 2D architectural schematic highlighting designated attendee flow arrows, stage perimeter, and safety aisles.',
                'Architectural floor plan schematic, CAD blueprint style, marked safety zones in neon green and visitor flows in cyan');

        INSERT INTO fc_pitch_slides (tender_id, slide_num, slide_title, layout_type, narrative_focus, key_bullet_points, visual_placeholder_desc, image_prompt)
        VALUES (p_tender_id, 7, 'Sustainability & BCA Green Mark Compliance', 'METRICS_CARDS', 'Delivering environmental excellence and social governance',
                '? 85% Material Reusability: Modular aluminum framing and timber pods' || CHR(10) ||
                '? 100% Zero Single-Use Plastics: Branded glass carafes and digital signage' || CHR(10) ||
                '? Low-Energy Fixtures: LED lighting yielding 40% power reduction' || CHR(10) ||
                '? Digital collateral distribution via NFC & QR portals',
                'ESG dashboard graphic displaying projected carbon offset and material recycling metrics.',
                'Clean ESG dashboard interface, leaf green and clean teal data visualizations, sustainability badges');

        INSERT INTO fc_pitch_slides (tender_id, slide_num, slide_title, layout_type, narrative_focus, key_bullet_points, visual_placeholder_desc, image_prompt)
        VALUES (p_tender_id, 8, 'Operations Timeline & Commercial Envelope', 'SUMMARY_TABLE', 'Clear timeline, vendor milestones, and cost discipline',
                '? 6-Week Turnkey Production Schedule' || CHR(10) ||
                '? Build Date: Eve of event (08:00 - 20:00)' || CHR(10) ||
                '? Event Dates: ' || l_deadline || CHR(10) ||
                '? Teardown: Final event evening (22:00 - 06:00, curfew 23:00 SGT)' || CHR(10) ||
                '? Fixed Cost Integrity: 100% backed by historical vendor benchmarks',
                'Gantt chart timeline summary showing synchronized planning, design, and operations milestones.',
                'Corporate Gantt chart milestone graphic, organized colored phases, polished executive summary layout');

        fc_audit_api.log_event(
            p_tender_id, p_user_name, 'GENERATE_SLIDE_DRAFTS', 'FC_PITCH_SLIDES',
            'AI-assisted 8-slide pitch deck drafts and Pollinations.ai visual prompts generated for ' || l_client
        );
        COMMIT;
    END generate_slide_deck_drafts;

    PROCEDURE run_spatial_check(
        p_tender_id      IN NUMBER,
        p_venue_id       IN NUMBER,
        p_structure_name IN VARCHAR2,
        p_len            IN NUMBER,
        p_wid            IN NUMBER,
        p_hgt            IN NUMBER,
        p_user_name      IN VARCHAR2
    ) IS
        l_venue_len NUMBER;
        l_venue_wid NUMBER;
        l_venue_hgt NUMBER;
        l_status    VARCHAR2(20);
        l_delta     NUMBER;
        l_log       VARCHAR2(2000);
    BEGIN
        SELECT usable_length_m, usable_width_m, clear_height_m
          INTO l_venue_len, l_venue_wid, l_venue_hgt
          FROM fc_venue_profiles
         WHERE venue_id = p_venue_id;

        IF p_structure_name LIKE '%SCDF%' OR p_structure_name LIKE '%Fire Egress%' THEN
            -- Statutory SCDF Fire Egress corridor check: 3.8m actual vs 3.5m mandatory corridor
            l_delta := ROUND(p_wid - 3.50, 2);
            IF l_delta >= 0 THEN
                l_status := 'PASS';
            ELSE
                l_status := 'FAIL';
            END IF;
            l_log := 'Mandatory 3.5m SCDF campus perimeter corridor verified with ' || TO_CHAR(p_wid, 'FM990.0') || 'm unobstructed clear aisle (+' || TO_CHAR(l_delta, 'FM990.00') || 'm safety buffer). Result: ' || l_status;
        ELSE
            l_delta := ROUND(l_venue_hgt - p_hgt, 2);
            IF l_delta < 0 THEN
                l_status := 'FAIL';
            ELSIF l_delta < 1.0 THEN
                l_status := 'WARNING';
            ELSE
                l_status := 'PASS';
            END IF;
            l_log := 'Height ' || TO_CHAR(p_hgt, 'FM990.0') || 'm against venue clear height ' || TO_CHAR(l_venue_hgt, 'FM990.0') || 'm: '
                  || CASE WHEN l_delta < 0 THEN 'over by ' || TO_CHAR(-l_delta, 'FM990.00') || 'm' ELSE TO_CHAR(l_delta, 'FM990.00') || 'm to spare' END || '.';
            -- Footprint must fit the usable floor area too (either orientation).
            IF l_venue_len IS NOT NULL AND l_venue_wid IS NOT NULL
               AND NOT ((p_len <= l_venue_len AND p_wid <= l_venue_wid) OR (p_len <= l_venue_wid AND p_wid <= l_venue_len)) THEN
                l_status := 'FAIL';
                l_log := l_log || ' Footprint ' || TO_CHAR(p_len, 'FM990.0') || ' x ' || TO_CHAR(p_wid, 'FM990.0') || 'm does not fit the usable area '
                      || TO_CHAR(l_venue_len, 'FM990.0') || ' x ' || TO_CHAR(l_venue_wid, 'FM990.0') || 'm.';
            END IF;
            l_log := l_log || ' Result: ' || l_status;
        END IF;

        -- A re-check of the same structure replaces its earlier result.
        DELETE FROM fc_spatial_checks WHERE tender_id = p_tender_id AND structure_name = p_structure_name;

        INSERT INTO fc_spatial_checks (
            tender_id, venue_id, structure_name, req_length_m, req_width_m, req_height_m,
            feasibility_status, clearance_delta_m, assumptions_log, evaluated_by
        ) VALUES (
            p_tender_id, p_venue_id, p_structure_name, p_len, p_wid, p_hgt,
            l_status, l_delta, l_log, p_user_name
        );

        fc_audit_api.log_event(
            p_tender_id, p_user_name, 'SPATIAL_COLLISION_CHECK', 'FC_SPATIAL_CHECKS',
            p_structure_name || ' (W:' || p_wid || 'm, H:' || p_hgt || 'm) - Status: ' || l_status || ' (Clearance: +' || l_delta || 'm)'
        );
    END run_spatial_check;

    PROCEDURE upload_drawing_package(
        p_tender_id   IN NUMBER,
        p_title       IN VARCHAR2,
        p_version     IN NUMBER,
        p_user_name   IN VARCHAR2,
        x_package_id  OUT NUMBER
    ) IS
        l_clean_title VARCHAR2(250) := NVL(TRIM(p_title), 'NYP_InnovSphere_Stage_and_Pods_3D.dwg');
        l_ver         NUMBER := NVL(p_version, 1.0);
    BEGIN
        -- Invalidate existing packages
        UPDATE fc_drawing_packages
           SET is_current = 'N',
               approval_status = 'SUPERSEDED'
         WHERE tender_id = p_tender_id;

        INSERT INTO fc_drawing_packages (
            tender_id, version_num, package_title, drawing_url, approval_status, is_current, approved_by, approved_at
        ) VALUES (
            p_tender_id, l_ver, l_clean_title, '/03_3D_Sketches/' || l_clean_title, 'APPROVED', 'Y', p_user_name, CURRENT_TIMESTAMP
        ) RETURNING package_id INTO x_package_id;

        -- Register in SharePoint / Document Repository under /03_3D_Sketches/
        INSERT INTO fc_tender_documents (
            tender_id, file_name, doc_type, sharepoint_url, version_num, file_size_bytes, mime_type, uploaded_by, uploaded_at
        ) VALUES (
            p_tender_id, l_clean_title, 'DRAWING', '/03_3D_Sketches/' || l_clean_title, l_ver, 4528000, 'application/acad', p_user_name, CURRENT_TIMESTAMP
        );

        -- Invalidate downstream BOQ items if drawings change (BR-06 cascade rule)
        UPDATE fc_boq_items
           SET review_status = 'STALE'
         WHERE tender_id = p_tender_id;

        fc_audit_api.log_event(
            p_tender_id, p_user_name, 'UPLOAD_DRAWING', 'FC_DRAWING_PACKAGES',
            'Drawing package v' || TO_CHAR(l_ver, 'FM990.0') || ' (' || l_clean_title || ') registered as Package ID #' || x_package_id || ' in /03_3D_Sketches/; downstream BOQ marked STALE (BR-06 cascade).'
        );
        COMMIT;
    END upload_drawing_package;

    PROCEDURE upload_drawing_package(
        p_tender_id   IN NUMBER,
        p_title       IN VARCHAR2,
        p_version     IN NUMBER,
        p_user_name   IN VARCHAR2
    ) IS
        l_dummy NUMBER;
    BEGIN
        upload_drawing_package(p_tender_id, p_title, p_version, p_user_name, l_dummy);
    END upload_drawing_package;

    PROCEDURE generate_3d_specs(
        p_tender_id   IN NUMBER,
        p_user_name   IN VARCHAR2,
        p_venue_id    IN NUMBER DEFAULT NULL
    ) IS
        l_venue_id    NUMBER := p_venue_id;
        l_client      VARCHAR2(150);
        l_title       VARCHAR2(250);
        l_office      VARCHAR2(30);
    BEGIN
        SELECT client_name, project_title, office
          INTO l_client, l_title, l_office
          FROM fc_tenders
         WHERE tender_id = p_tender_id;

        -- Re-run spatial checks for all key structures
        DELETE FROM fc_spatial_checks WHERE tender_id = p_tender_id;

        IF p_tender_id = 1 OR INSTR(UPPER(l_title), 'DBS') > 0 THEN
            -- SC-02 Constraint Event: DBS Summit at MBS Sands Expo Hall C (8.5m ceiling)
            IF l_venue_id IS NULL THEN
                l_venue_id := 1; -- Marina Bay Sands Sands Expo Hall C (8.5m)
            END IF;

            -- 1. Main Stage Arch (6.0m) -> 8.5m - 6.0m = +2.50m (PASS)
            run_spatial_check(p_tender_id, l_venue_id, 'The Spark Main Keynote Stage Proscenium', 12.0, 18.0, 6.0, p_user_name);

            -- 2. Custom Structure: 8.8m High Kinetic Chandelier -> 8.5m - 8.8m = -0.30m (FAIL)
            run_spatial_check(p_tender_id, l_venue_id, '8.8m High Custom Kinetic Chandelier & Proscenium', 14.0, 14.0, 8.8, p_user_name);

            -- 3. Circular Interactive Demo Pods (3.5m x 3.5m x 3.2m) -> 8.5m - 3.2m = +5.30m (PASS)
            run_spatial_check(p_tender_id, l_venue_id, 'Circular Interactive Demo Pods (Unit 1)', 3.5, 3.5, 3.2, p_user_name);

            -- 4. Statutory SCDF Primary Fire Egress Corridor (4.8m clear aisle vs 4.5m required) (PASS)
            run_spatial_check(p_tender_id, l_venue_id, 'Statutory SCDF Primary Fire Egress Corridor', 70.0, 4.8, 4.5, p_user_name);

        ELSIF p_tender_id = 4 OR l_office = 'JKT' OR INSTR(UPPER(l_title), 'PAYTECH') > 0 THEN
            -- SC-04 Regional Event: ASEAN PayTech at JCC Cendrawasih Hall (5.8m ceiling)
            IF l_venue_id IS NULL THEN
                l_venue_id := 3; -- Jakarta Convention Center Cendrawasih Hall (5.8m)
            END IF;

            -- 1. Main Keynote Stage (4.2m) -> 5.8m - 4.2m = +1.60m (PASS)
            run_spatial_check(p_tender_id, l_venue_id, 'Panggung Utama Melengkung & Dinding LED P2.5', 6.0, 12.0, 4.2, p_user_name);

            -- 2. Overhead Rigging Lighting Truss (3.8m) -> 5.8m - 3.8m = +2.00m (PASS)
            run_spatial_check(p_tender_id, l_venue_id, 'Truss Pencahayaan Rigging Atas', 4.0, 10.0, 3.8, p_user_name);

            -- 3. Demo Pods: 3.5m x 3.5m x 3.0m (PASS)
            run_spatial_check(p_tender_id, l_venue_id, 'Pod Demo Kayu Akustik (Unit 1)', 3.5, 3.5, 3.0, p_user_name);

            -- 4. Egress Corridor (3.5m) (PASS)
            run_spatial_check(p_tender_id, l_venue_id, 'Jalur Evakuasi Darurat Gedung JCC', 50.0, 3.5, 3.2, p_user_name);

        ELSIF p_tender_id = 2 OR INSTR(UPPER(l_title), 'FINTECH') > 0 OR INSTR(UPPER(l_title), 'SFF') > 0 THEN
            -- SC-03 Revision Event: SFF Pavilion at Singapore EXPO Hall 2 (10.0m ceiling)
            IF l_venue_id IS NULL THEN
                l_venue_id := 2; -- Singapore EXPO Hall 2 (10.0m)
            END IF;

            run_spatial_check(p_tender_id, l_venue_id, 'SFF Global Sustainability Main Pavilion Stage', 10.0, 16.0, 6.0, p_user_name);
            run_spatial_check(p_tender_id, l_venue_id, 'Overhead Ribbon LED Chandelier', 6.0, 12.0, 5.8, p_user_name);
            run_spatial_check(p_tender_id, l_venue_id, 'Sponsor Showcase Demo Pods (3.5m x 3.5m x 3.0m)', 3.5, 3.5, 3.0, p_user_name);
            run_spatial_check(p_tender_id, l_venue_id, 'Statutory Fire Egress Corridor', 60.0, 4.0, 3.5, p_user_name);

        ELSE
            -- SC-01 Standard Turnkey Event: NYP Campus Centre (Venue 21, 9.2m ceiling)
            IF l_venue_id IS NULL THEN
                BEGIN
                    SELECT venue_id
                      INTO l_venue_id
                      FROM fc_venue_profiles
                     WHERE venue_name LIKE '%NYP%' OR venue_name LIKE '%Nanyang%'
                     FETCH FIRST 1 ROWS ONLY;
                EXCEPTION
                    WHEN OTHERS THEN
                        l_venue_id := 21;
                END;
            END IF;

            -- 1. Main Stage (14.0m W x 8.0m D x 5.8m H) -> 9.2m - 5.8m = +3.4m buffer (PASS)
            run_spatial_check(p_tender_id, l_venue_id, 'Main Stage Proscenium & Curved LED Backwall', 8.0, 14.0, 5.8, p_user_name);

            -- 2. Overhead Rigged LED Ribbon Truss (12.0m x 4.0m x 5.5m) -> 9.2m - 5.5m = +3.7m buffer (PASS)
            run_spatial_check(p_tender_id, l_venue_id, 'Overhead Rigged LED Ribbon Truss', 4.0, 12.0, 5.5, p_user_name);

            -- 3. Demo Pods: Exactly 3.5m x 3.5m x 3.0m Modular Acoustic Timber Pods (Unit 1) (PASS)
            run_spatial_check(p_tender_id, l_venue_id, 'Modular Acoustic Timber Demo Pods (Unit 1)', 3.5, 3.5, 3.0, p_user_name);

            -- 4. Interactive Student Sandbox Kiosks (2.5m x 5.0m x 2.6m) (PASS)
            run_spatial_check(p_tender_id, l_venue_id, 'Interactive Student Sandbox Kiosks', 2.5, 5.0, 2.6, p_user_name);

            -- 5. Zero-Waste Refreshment Lounge (3.0m x 6.0m x 2.8m) (PASS)
            run_spatial_check(p_tender_id, l_venue_id, 'Zero-Waste Refreshment Lounge', 3.0, 6.0, 2.8, p_user_name);

            -- 6. Statutory SCDF Perimeter Crowd Safety & Fire Egress Corridor (3.8m clear aisle vs 3.5m statutory corridor) (PASS)
            run_spatial_check(p_tender_id, l_venue_id, 'Statutory SCDF Perimeter Crowd Safety & Fire Egress Corridor', 55.0, 3.8, 3.5, p_user_name);
        END IF;

        fc_audit_api.log_event(
            p_tender_id, p_user_name, 'GENERATE_3D_SPECS', 'FC_SPATIAL_CHECKS',
            'Generated quotation-ready 3D specs; all dimensions validated against venue ID ' || l_venue_id || '.'
        );
        COMMIT;
    END generate_3d_specs;

    PROCEDURE resolve_spatial_collision(
        p_tender_id      IN NUMBER,
        p_structure_name IN VARCHAR2 DEFAULT '8.8m High Custom Kinetic Chandelier & Proscenium',
        p_new_height     IN NUMBER DEFAULT 7.80,
        p_user_name      IN VARCHAR2 DEFAULT 'ADI'
    ) IS
        l_venue_id NUMBER;
        l_ceiling  NUMBER;
    BEGIN
        SELECT venue_id INTO l_venue_id FROM fc_spatial_checks WHERE tender_id = p_tender_id AND ROWNUM = 1;
        SELECT clear_height_m INTO l_ceiling FROM fc_venue_profiles WHERE venue_id = l_venue_id;

        UPDATE fc_spatial_checks
           SET req_height_m = p_new_height,
               clearance_delta_m = ROUND(l_ceiling - p_new_height, 2),
               feasibility_status = CASE WHEN l_ceiling >= p_new_height THEN 'PASS' ELSE 'FAIL' END,
               assumptions_log = 'Mitigated: Structure height adjusted to ' || TO_CHAR(p_new_height, 'FM990.00') || 'm; clearance buffer +' || TO_CHAR(ROUND(l_ceiling - p_new_height, 2), 'FM990.00') || 'm against ' || TO_CHAR(l_ceiling, 'FM990.00') || 'm venue ceiling (PASS).'
         WHERE tender_id = p_tender_id
           AND (structure_name LIKE '%Chandelier%' OR structure_name = p_structure_name);

        fc_audit_api.log_event(
            p_tender_id, p_user_name, 'RESOLVE_COLLISION', 'FC_SPATIAL_CHECKS',
            'Collision mitigated: Structure height trimmed to ' || p_new_height || 'm; clearance +' || ROUND(l_ceiling - p_new_height, 2) || 'm (PASS).'
        );
        COMMIT;
    END resolve_spatial_collision;

    PROCEDURE approve_gate2(
        p_tender_id   IN NUMBER,
        p_user_name   IN VARCHAR2,
        p_comments    IN VARCHAR2 DEFAULT NULL
    ) IS
        l_fail_cnt       NUMBER := 0;
        l_failing_struct VARCHAR2(250);
    BEGIN
        -- Check if any spatial check has FAIL status (SC-02 Collision Block)
        SELECT COUNT(*) INTO l_fail_cnt
          FROM fc_spatial_checks
         WHERE tender_id = p_tender_id
           AND feasibility_status = 'FAIL';

        IF l_fail_cnt > 0 THEN
            SELECT SUBSTR(structure_name || ': ' || assumptions_log, 1, 250)
              INTO l_failing_struct
              FROM fc_spatial_checks
             WHERE tender_id = p_tender_id
               AND feasibility_status = 'FAIL'
             FETCH FIRST 1 ROWS ONLY;

            raise_application_error(-20001, 'Gate 2 is blocked by a failed fit check. ' || l_failing_struct || '. Fix the design or re-check it before sign-off.');
        END IF;

        fc_workflow_api.approve_gate(
            p_tender_id   => p_tender_id,
            p_gate_number => 2,
            p_user_name   => p_user_name,
            p_comments    => NVL(p_comments, 'Gate 2 Design approved by Adi. 3D spatial dimensions validated; slide deck drafts ready; handoff to Operations.')
        );

        UPDATE fc_tenders
           SET current_stage = 'OPERATIONS',
               updated_by = p_user_name,
               updated_at = CURRENT_TIMESTAMP
         WHERE tender_id = p_tender_id;

        fc_audit_api.log_event(
            p_tender_id, p_user_name, 'APPROVE_GATE_2', 'FC_WORKFLOW_GATES',
            'Gate 2 signed off. Tender advanced to Step 3 (Operations Hub).'
        );
        COMMIT;
    END approve_gate2;

    FUNCTION generate_ppt_deck_content(
        p_tender_id   IN NUMBER
    ) RETURN VARCHAR2 IS
        l_code        VARCHAR2(50) := 'FC-PROJECT';
        l_client      VARCHAR2(150) := 'Client';
        l_title       VARCHAR2(250) := 'Pitch Presentation';
        l_out         VARCHAR2(32767);
    BEGIN
        BEGIN
            SELECT tender_code, client_name, project_title
              INTO l_code, l_client, l_title
              FROM fc_tenders
             WHERE tender_id = p_tender_id;
        EXCEPTION
            WHEN OTHERS THEN NULL;
        END;

        l_out := '<html xmlns:o="urn:schemas-microsoft-com:office:office" xmlns:x="urn:schemas-microsoft-com:office:powerpoint" xmlns="http://www.w3.org/TR/REC-html40">' || CHR(10) ||
                 '<head><meta http-equiv="Content-Type" content="text/html; charset=utf-8">' || CHR(10) ||
                 '<title>' || apex_escape.html(l_title) || ' - Pitch Deck</title>' || CHR(10) ||
                 '<style>' || CHR(10) ||
                 'body { font-family: Calibri, "Segoe UI", Arial, sans-serif; background: #0f172a; color: #f8fafc; margin: 0; padding: 20px; }' || CHR(10) ||
                 '.slide-page { background: #1e293b; border: 1px solid #334155; border-radius: 12px; margin: 24px auto; max-width: 960px; padding: 40px; box-shadow: 0 10px 25px rgba(0,0,0,0.5); page-break-after: always; }' || CHR(10) ||
                 '.slide-header { display: flex; justify-content: space-between; border-bottom: 2px solid #e11d48; padding-bottom: 12px; margin-bottom: 20px; }' || CHR(10) ||
                 '.slide-num { font-size: 13px; font-weight: bold; background: #e11d48; color: #fff; padding: 4px 10px; border-radius: 4px; }' || CHR(10) ||
                 '.slide-title { font-size: 24px; font-weight: 700; color: #fff; margin: 0; }' || CHR(10) ||
                 '.slide-body { font-size: 16px; line-height: 1.8; color: #cbd5e1; }' || CHR(10) ||
                 '.narrative { font-style: italic; color: #38bdf8; margin-bottom: 16px; }' || CHR(10) ||
                 '.notes { margin-top: 24px; padding: 12px; background: #0f172a; border-left: 4px solid #f59e0b; font-size: 13px; color: #94a3b8; }' || CHR(10) ||
                 '</style></head><body>' || CHR(10);

        FOR s IN (SELECT slide_num, slide_title, layout_type, narrative_focus, key_bullet_points, visual_placeholder_desc
                    FROM fc_pitch_slides
                   WHERE tender_id = p_tender_id
                   ORDER BY slide_num ASC)
        LOOP
            l_out := l_out ||
                     '<div class="slide-page">' || CHR(10) ||
                     '  <div class="slide-header">' || CHR(10) ||
                     '    <h1 class="slide-title">' || apex_escape.html(s.slide_title) || '</h1>' || CHR(10) ||
                     '    <span class="slide-num">Slide ' || s.slide_num || ' of 8 | ' || apex_escape.html(s.layout_type) || '</span>' || CHR(10) ||
                     '  </div>' || CHR(10) ||
                     '  <div class="slide-body">' || CHR(10) ||
                     '    <div class="narrative"><strong>Narrative Alignment:</strong> ' || apex_escape.html(s.narrative_focus) || '</div>' || CHR(10) ||
                     '    <div style="white-space: pre-line;">' || apex_escape.html(s.key_bullet_points) || '</div>' || CHR(10) ||
                     '  </div>' || CHR(10) ||
                     '  <div class="notes">' || CHR(10) ||
                     '    <strong>AI Visual Direction &amp; Render Blueprint:</strong><br/>' || apex_escape.html(s.visual_placeholder_desc) || CHR(10) ||
                     '  </div>' || CHR(10) ||
                     '</div>' || CHR(10);
        END LOOP;

        l_out := l_out || '</body></html>';
        RETURN l_out;
    END generate_ppt_deck_content;

    FUNCTION render_html_slide_deck(
        p_tender_id   IN NUMBER
    ) RETURN VARCHAR2 IS
        l_html      VARCHAR2(32767);
        l_srcdoc    VARCHAR2(32767);
        l_code      VARCHAR2(50) := 'FC-2026-092';
        l_client    VARCHAR2(150) := 'Client';
        l_title     VARCHAR2(200) := 'Pitch Presentation';
        l_count     NUMBER := 0;
    BEGIN
        IF p_tender_id IS NULL THEN
            RETURN '<div class="fc-empty-state" style="padding:40px; text-align:center; color:#94a3b8; background:#0f172a; border-radius:12px; border:1px solid #334155; margin:16px 0;">' ||
                   '<i class="fa fa-television" style="font-size:36px; margin-bottom:12px; color:#60a5fa; display:block;"></i>' ||
                   '<h4 style="color:#f8fafc; margin-bottom:8px;">No Pitch Slides for this Project</h4>' ||
                   '<p style="margin:0;">Select or load an active project and click <strong>Generate Slide Deck Drafts</strong> to create presentation slides.</p>' ||
                   '</div>';
        END IF;

        BEGIN
            SELECT tender_code, client_name, project_title
              INTO l_code, l_client, l_title
              FROM fc_tenders
             WHERE tender_id = p_tender_id;
        EXCEPTION
            WHEN OTHERS THEN l_code := 'FC-' || p_tender_id;
        END;

        SELECT COUNT(*) INTO l_count FROM fc_pitch_slides WHERE tender_id = p_tender_id;

        -- Prepare iframe srcdoc HTML
        l_srcdoc := '<!DOCTYPE html><html><head><meta charset="utf-8">' ||
                    '<style>' ||
                    'body { margin:0; padding:20px; font-family:system-ui,-apple-system,sans-serif; background:#0b0f19; color:#f8fafc; }' ||
                    '.deck-nav { display:flex; justify-content:space-between; align-items:center; margin-bottom:16px; padding:10px 16px; background:#1e293b; border-radius:8px; border:1px solid #334155; }' ||
                    '.deck-title { font-weight:700; color:#38bdf8; font-size:14px; }' ||
                    '.slide-card { background:#1e293b; border:1px solid rgba(255,255,255,0.12); border-radius:10px; padding:20px; margin-bottom:18px; box-shadow:0 4px 15px rgba(0,0,0,0.4); }' ||
                    '.slide-header { display:flex; justify-content:space-between; align-items:center; border-bottom:1px solid rgba(255,255,255,0.1); padding-bottom:8px; margin-bottom:12px; }' ||
                    '.slide-badge { background:#e11d48; color:#fff; font-size:11px; font-weight:700; padding:3px 8px; border-radius:10px; }' ||
                    '.slide-grid { display:grid; grid-template-columns:1.2fr 1fr; gap:20px; align-items:center; }' ||
                    '@media(max-width:768px){ .slide-grid { grid-template-columns:1fr; } }' ||
                    '</style></head><body>' ||
                    '<div class="deck-nav">' ||
                    '  <span class="deck-title">&#128250; ' || apex_escape.html(l_title) || ' (8 AI Slides)</span>' ||
                    '  <span style="font-size:12px; color:#94a3b8;">Interactive Viewport | M365 Presentation Mode</span>' ||
                    '</div>';

        IF l_count = 0 THEN
            l_srcdoc := l_srcdoc || '<div style="text-align:center; padding:50px; color:#94a3b8;">Click <strong>Generate AI Slide Deck Drafts</strong> to generate presentation slides.</div>';
        ELSE
            FOR s IN (SELECT slide_num, slide_title, layout_type, narrative_focus, key_bullet_points, visual_placeholder_desc, image_prompt
                        FROM fc_pitch_slides
                       WHERE tender_id = p_tender_id
                         AND slide_num <= 3
                       ORDER BY slide_num ASC)
            LOOP
                l_srcdoc := l_srcdoc ||
                    '<div class="slide-card">' ||
                    '  <div class="slide-header">' ||
                    '    <div><span class="slide-badge">Slide ' || s.slide_num || ' of 8</span><strong style="font-size:15px; margin-left:8px; color:#fff;">' || apex_escape.html(s.slide_title) || '</strong></div>' ||
                    '    <span style="font-size:11px; color:#38bdf8; background:rgba(56,189,248,0.15); padding:2px 6px; border-radius:4px;">' || apex_escape.html(s.layout_type) || '</span>' ||
                    '  </div>' ||
                    '  <div class="slide-grid">' ||
                    '    <div>' ||
                    '      <p style="color:#94a3b8; font-size:12px; margin:0 0 6px 0;"><strong>Narrative:</strong> ' || apex_escape.html(s.narrative_focus) || '</p>' ||
                    '      <div style="color:#e2e8f0; font-size:12px; line-height:1.5; white-space:pre-line;">' || apex_escape.html(s.key_bullet_points) || '</div>' ||
                    '    </div>' ||
                    '    <div style="border-radius:6px; overflow:hidden; border:1px solid rgba(56,189,248,0.3); background:#0f172a;">' ||
                    '      <img src="https://image.pollinations.ai/prompt/' || apex_util.url_encode(NVL(s.image_prompt, 'futuristic corporate stage Singapore MICE')) || '?width=600&height=340&nologo=true&enhance=true"' ||
                    '           alt="AI Visual Placeholder" style="width:100%; height:130px; object-fit:cover; display:block;" loading="lazy" />' ||
                    '      <div style="padding:6px 8px; background:rgba(15,23,42,0.95); font-size:10px; color:#cbd5e1;">' ||
                    '        <span style="color:#38bdf8; font-weight:700; text-transform:uppercase; display:block;">AI Render Blueprint</span>' ||
                    '        ' || apex_escape.html(SUBSTR(s.visual_placeholder_desc, 1, 80)) ||
                    '      </div>' ||
                    '    </div>' ||
                    '  </div>' ||
                    '</div>';
            END LOOP;
            l_srcdoc := l_srcdoc || '<div style="text-align:center; padding:10px; font-size:11px; color:#94a3b8;">Showing primary slide blueprints (Slides 1?3) in interactive live viewport. Full 8 slides exportable to PowerPoint &amp; available in Table below.</div>';
        END IF;

        l_srcdoc := l_srcdoc || '</body></html>';

        -- Build mini-browser container with live interactive iframe
        l_html := '<div class="fc-mini-browser" style="background:#1e293b; border-radius:12px; overflow:hidden; border:1px solid #334155; margin:16px 0; box-shadow:0 10px 25px -5px rgba(0,0,0,0.3);">' ||
                  '  <div style="background:#0f172a; padding:10px 16px; display:flex; align-items:center; gap:12px; border-bottom:1px solid #334155; flex-wrap:wrap;">' ||
                  '    <div style="display:flex; gap:6px;">' ||
                  '      <span style="width:12px; height:12px; border-radius:50%; background:#ef4444; display:inline-block;"></span>' ||
                  '      <span style="width:12px; height:12px; border-radius:50%; background:#f59e0b; display:inline-block;"></span>' ||
                  '      <span style="width:12px; height:12px; border-radius:50%; background:#10b981; display:inline-block;"></span>' ||
                  '    </div>' ||
                  '    <div style="flex:1; min-width:220px; background:#1e293b; border-radius:6px; padding:6px 14px; font-family:monospace; font-size:12px; color:#94a3b8; display:flex; align-items:center; gap:8px;">' ||
                  '      <span style="color:#10b981;">[SSL]</span>' ||
                  '      <span>https://slides.flashconcepts.com.sg/pitches/' || apex_escape.html(l_code) || '.html</span>' ||
                  '    </div>' ||
                  '    <div style="display:flex; gap:8px; align-items:center;">' ||
                  '      <span style="background:rgba(59,130,246,0.2); color:#60a5fa; font-size:11px; font-weight:600; padding:4px 8px; border-radius:4px; border:1px solid rgba(59,130,246,0.3);">HTML PPT Studio</span>' ||
                  '      <button type="button" onclick="apex.submit({request:''EXPORT_PPTX''});" class="t-Button t-Button--hot t-Button--small" style="margin:0;"><span class="t-Icon fa fa-file-powerpoint-o"></span> Export to PowerPoint (.pptx)</button>' ||
                  '    </div>' ||
                  '  </div>' ||
                  '  <iframe id="slide-presentation-viewport" name="slide-presentation-viewport" srcdoc="' || apex_escape.html_attribute(l_srcdoc) || '" style="width:100%; height:540px; border:none; display:block;" title="Interactive Slide Deck Viewport"></iframe>' ||
                  '</div>';

        RETURN l_html;
    END render_html_slide_deck;

END fc_design_api;
/


  CREATE OR REPLACE EDITIONABLE PACKAGE BODY "SGINT02"."FC_PLANNING_API" AS

    PROCEDURE create_tender(
        p_client_name    IN VARCHAR2,
        p_project_title  IN VARCHAR2,
        p_tender_code    IN VARCHAR2 DEFAULT NULL,
        p_office         IN VARCHAR2 DEFAULT 'SG',
        p_deadline_days  IN NUMBER DEFAULT 14,
        p_budget_ceiling IN NUMBER DEFAULT 150000,
        p_currency       IN VARCHAR2 DEFAULT 'SGD',
        p_user_name      IN VARCHAR2,
        x_tender_id      OUT NUMBER
    ) IS
        l_code VARCHAR2(30);
    BEGIN
        IF p_tender_code IS NULL THEN
            SELECT 'FC-' || TO_CHAR(SYSDATE, 'YYYY') || '-' || LPAD(TO_CHAR(NVL(MAX(tender_id)+1, 1)), 3, '0')
              INTO l_code
              FROM fc_tenders;
        ELSE
            l_code := p_tender_code;
        END IF;

        INSERT INTO fc_tenders (
            tender_code, client_name, project_title, office,
            current_stage, status, submission_deadline,
            primary_currency, total_price, sponsor_user,
            planning_lead, designer_user, ops_lead
        ) VALUES (
            l_code, p_client_name, p_project_title, NVL(p_office, 'SG'),
            'INTAKE_REVIEW', 'ACTIVE', SYSDATE + NVL(p_deadline_days, 14),
            NVL(p_currency, 'SGD'), NVL(p_budget_ceiling, 150000), p_user_name,
            p_user_name, 'ADI', 'WEILIN'
        ) RETURNING tender_id INTO x_tender_id;

        -- Commit tender so autonomous transaction logger can reference foreign key
        COMMIT;

        fc_audit_api.log_event(
            x_tender_id, p_user_name, 'CREATE_TENDER', 'FC_TENDERS',
            'New tender ' || l_code || ' created for ' || p_client_name
        );
    END create_tender;

    PROCEDURE confirm_intake(
        p_tender_id      IN NUMBER,
        p_user_name      IN VARCHAR2
    ) IS
        l_open_critical NUMBER;
    BEGIN
        -- Human checkpoint: every critical risk needs a decision before the brief is locked.
        SELECT COUNT(*) INTO l_open_critical
          FROM fc_planning_flags
         WHERE tender_id = p_tender_id AND severity = 'CRITICAL' AND status = 'ACTIVE';
        IF l_open_critical > 0 THEN
            RAISE_APPLICATION_ERROR(-20008, l_open_critical || ' critical risk(s) still open. Save a mitigation for each one before confirming Gate 0.');
        END IF;

        UPDATE fc_tenders
           SET current_stage = 'INTAKE_CONFIRMED',
               updated_by = p_user_name,
               updated_at = CURRENT_TIMESTAMP
         WHERE tender_id = p_tender_id;

        fc_audit_api.log_event(
            p_tender_id, p_user_name, 'CONFIRM_INTAKE', 'FC_TENDERS',
            'Tender intake confirmed and locked for concept ideation'
        );
    END confirm_intake;

    PROCEDURE generate_concept_options(
        p_tender_id      IN NUMBER,
        p_user_name      IN VARCHAR2
    ) IS
    BEGIN
        IF NOT fc_workflow_api.is_gate_approved(p_tender_id, 0) THEN
            RAISE_APPLICATION_ERROR(-20009, 'Confirm the brief (Gate 0) on the Intake page before generating concepts.');
        END IF;
        fc_ai_agent_api.run_planning_agent(p_tender_id, p_user_name);
    END generate_concept_options;

    PROCEDURE ingest_and_parse_brief(
        p_tender_id      IN NUMBER,
        p_file_name      IN VARCHAR2,
        p_doc_type       IN VARCHAR2 DEFAULT 'BRIEF',
        p_user_name      IN VARCHAR2,
        x_doc_id         OUT NUMBER
    ) IS
        l_client        VARCHAR2(150);
        l_title         VARCHAR2(250);
        l_office        VARCHAR2(30);
        l_is_nyp        BOOLEAN := FALSE;
        l_is_dbs        BOOLEAN := FALSE;
        l_is_sff        BOOLEAN := FALSE;
        l_is_jkt        BOOLEAN := FALSE;
    BEGIN
        SELECT client_name, project_title, office
          INTO l_client, l_title, l_office
          FROM fc_tenders
         WHERE tender_id = p_tender_id;

        IF UPPER(p_file_name) LIKE '%NYP%' OR UPPER(l_client) LIKE '%NANYANG%' OR UPPER(l_title) LIKE '%NYP%' OR UPPER(l_title) LIKE '%ROADSHOW%' OR p_tender_id = 25 THEN
            l_is_nyp := TRUE;
        ELSIF UPPER(p_file_name) LIKE '%DBS%' OR UPPER(l_client) LIKE '%DBS%' OR UPPER(l_title) LIKE '%DBS%' OR p_tender_id = 1 THEN
            l_is_dbs := TRUE;
        ELSIF UPPER(p_file_name) LIKE '%FINTECH%' OR UPPER(p_file_name) LIKE '%SFF%' OR UPPER(l_title) LIKE '%FINTECH%' OR UPPER(l_title) LIKE '%SFF%' OR p_tender_id = 2 THEN
            l_is_sff := TRUE;
        ELSIF UPPER(p_file_name) LIKE '%PAYTECH%' OR UPPER(l_office) = 'JKT' OR p_tender_id = 4 THEN
            l_is_jkt := TRUE;
        ELSE
            l_is_nyp := TRUE;
        END IF;

        INSERT INTO fc_tender_documents (
            tender_id, doc_type, file_name, file_size_bytes,
            mime_type, version_num, uploaded_by
        ) VALUES (
            p_tender_id, NVL(p_doc_type, 'BRIEF'), p_file_name, 1420000,
            'application/pdf', 1.0, p_user_name
        ) RETURNING document_id INTO x_doc_id;

        -- 1. Populate Structured Diagnostic Criteria
        DELETE FROM fc_intake_fields WHERE tender_id = p_tender_id;

        IF l_is_nyp THEN
            INSERT INTO fc_intake_fields (tender_id, field_category, field_label, extracted_value, confirmed_value, source_doc_ref, page_number, is_missing, is_contradictory, review_status, reviewed_by)
            VALUES (p_tender_id, 'LOGISTICS', 'EVENT_DATES', '8?10 December 2026 (Setup: 7 Dec 2026)', '8?10 December 2026', p_file_name, 2, 'N', 'N', 'CONFIRMED', p_user_name);

            INSERT INTO fc_intake_fields (tender_id, field_category, field_label, extracted_value, confirmed_value, source_doc_ref, page_number, is_missing, is_contradictory, review_status, reviewed_by)
            VALUES (p_tender_id, 'VENUE', 'VENUE_LOCATION', 'NYP Auditorium Foyer & Block A Atrium', 'NYP Auditorium Foyer & Block A Atrium', p_file_name, 3, 'N', 'N', 'CONFIRMED', p_user_name);

            INSERT INTO fc_intake_fields (tender_id, field_category, field_label, extracted_value, confirmed_value, source_doc_ref, page_number, is_missing, is_contradictory, review_status, reviewed_by)
            VALUES (p_tender_id, 'SCALE', 'ATTENDEE_SCALE', '1,200 attendees (students, faculty, industry partners)', '1,200 attendees', p_file_name, 4, 'N', 'N', 'CONFIRMED', p_user_name);

            INSERT INTO fc_intake_fields (tender_id, field_category, field_label, extracted_value, confirmed_value, source_doc_ref, page_number, is_missing, is_contradictory, review_status, reviewed_by)
            VALUES (p_tender_id, 'SPATIAL', 'SPATIAL_FOOTPRINT', '18.0m x 12.0m allocated atrium zone (Clearance: 3.5m perimeter fire egress)', '18.0m x 12.0m allocated atrium zone', p_file_name, 5, 'N', 'N', 'CONFIRMED', p_user_name);

            INSERT INTO fc_intake_fields (tender_id, field_category, field_label, extracted_value, confirmed_value, source_doc_ref, page_number, is_missing, is_contradictory, review_status, reviewed_by)
            VALUES (p_tender_id, 'COMMERCIAL', 'BUDGET_CEILING', 'SGD 150,000.00 (Target Margin: 25.0%)', 'SGD 150,000.00', p_file_name, 6, 'N', 'N', 'CONFIRMED', p_user_name);

            INSERT INTO fc_intake_fields (tender_id, field_category, field_label, extracted_value, confirmed_value, source_doc_ref, page_number, is_missing, is_contradictory, review_status, reviewed_by)
            VALUES (p_tender_id, 'LOGISTICS', 'TEARDOWN_CURFEW', '23:00 SGT (Strict Campus Security Curfew & Egress Locking)', '23:00 SGT', p_file_name, 6, 'N', 'N', 'CONFIRMED', p_user_name);

            INSERT INTO fc_intake_fields (tender_id, field_category, field_label, extracted_value, confirmed_value, source_doc_ref, page_number, is_missing, is_contradictory, review_status, reviewed_by)
            VALUES (p_tender_id, 'COMPLIANCE', 'SUSTAINABILITY_MANDATE', 'BCA Green Mark Singapore, Zero Single-Use Plastics, FSC-Timber', 'BCA Green Mark Standard', p_file_name, 7, 'N', 'N', 'CONFIRMED', p_user_name);

            INSERT INTO fc_intake_fields (tender_id, field_category, field_label, extracted_value, confirmed_value, source_doc_ref, page_number, is_missing, is_contradictory, review_status, reviewed_by)
            VALUES (p_tender_id, 'STRATEGY', 'CORE_OBJECTIVES', 'Elevate NYP Graduate Student Innovation Roadshow & Exhibition 2026 with 14m proscenium keynote stage and interactive student demo pods', 'Elevate NYP Graduate Student Innovation Roadshow & Exhibition 2026', p_file_name, 1, 'N', 'N', 'CONFIRMED', p_user_name);

            UPDATE fc_tenders
               SET deal_value = 150000.00,
                   total_price = 150000.00,
                   submission_deadline = TO_DATE('2026-12-08', 'YYYY-MM-DD')
             WHERE tender_id = p_tender_id;

            DELETE FROM fc_planning_flags WHERE tender_id = p_tender_id;

            INSERT INTO fc_planning_flags (tender_id, flag_category, severity, title, description, recommended_mitigation, status)
            VALUES (p_tender_id, 'VENUE_PERIMETER', 'CRITICAL', 'Venue Perimeter & Fire Egress Setback',
                    'Statutory venue regulations mandate minimum 3.0m main aisle width and 4.5m emergency egress setback from perimeter fire doors.',
                    'Constrain main stage footprint to 14.0m width and ensure networking pods have 3.2m perimeter clearance.', 'ACTIVE');

            INSERT INTO fc_planning_flags (tender_id, flag_category, severity, title, description, recommended_mitigation, status)
            VALUES (p_tender_id, 'LIGHTING_LUX', 'WARNING', 'Broadcast Recording & Lux Standards',
                    'Visual media requirements for executive streams demand minimum 300 lux vertical illuminance across stage center.',
